Object.assign(CHOICES, {
  wolf: { q: [['narr', '狼妖王倒在空窝前，喘着粗气。它没有再扑上来，只是把身子横在那个空窝前面。'], ['geng', '……让开。我来补一箭。']], opts: [
    { l: '杀了它，拿狼王牙', set: { wolfKilled: 1 }, key: 'wolftooth', lines: [['narr', '你走过去。狼妖王看着你，没有动。'], ['narr', '它最后看了一眼那个空窝。'], ['geng', '……'], ['narr', '耿伯的弓慢慢放了下来，手一直在抖。'], ['xiaohu', '……它疼了十年。'], ['narr', '小虎说完这句，就再也没说话。']] },
    { l: '耿伯，把你十年前做的事说出来', aff: { zhen: 1 }, set: { wolfSpared: 1 }, key: 'wolftooth', lines: [
      ['me', '耿伯，小虎脖子上那颗乳牙，你认得吧？'],
      ['geng', '……认得。'],
      ['geng', '十年前，我掏了这个窝。三只狼崽，皮卖了九两银子。我给我家那口子抓了药……药也没救回来。'],
      ['geng', '那年冬天，林子里的狼嚎了一整个月。我以为它们是在嚎我家那口子。'],
      ['geng', '……原来它们嚎的，是自己的崽。'],
      ['narr', '耿伯扔下弓，跪在空窝前，从怀里摸出一串发黑的狼牙，一颗一颗摆进窝里。'],
      ['geng', '……对不住。是我对不住你。'],
      ['narr', '狼妖王看了他很久。然后它低下头，舔了舔小虎的脸，转身走进了林子深处。'],
      ['narr', '它刚才趴着的地方，留下了一颗狼牙。'],
      ['xiaohu', '它说……它记住你了。不是记仇的那种记住。']] }] },
  ngocNail2: { q: [['ngoc', '那根钉子呢？你从古树里拿出来的那根。']], opts: [
    { l: '给清虚道长了，他说替我镇着', aff: { ngoc: -1 }, lines: [['narr', '「啪」——药碾子掉在地上。'], ['ngoc', '你把它给了谁？！'], ['me', '清虚道长。他救了我——'], ['ngoc', '……'], ['ngoc', '没事。我手滑。'], ['narr', '她弯腰去捡药碾子。你看见她鞋边上，沾着一块黑风林才有的红泥。']] },
    { l: '……我也不知道该不该给他', aff: { ngoc: 1 }, lines: [['ngoc', '你给了？'], ['me', '给了。当时我刚醒，脑子昏。'], ['ngoc', '……下回，先问问我。'], ['ngoc', '我不是要管你。药铺的老板娘见的人多，看人准。'], ['narr', '她鞋边上沾着一块红泥。黑风林才有的那种红泥。']] }] },
  amulet: { q: [['ngoc', '……拿着。路边随手买的。']], opts: [
    { l: '这针脚……是你自己缝的吧？', aff: { ngoc: 2 }, lines: [['ngoc', '……买的！'], ['me', '那你手指上的针眼呢？'], ['ngoc', '被药碾子夹的。'], ['narr', '纸鹤扑棱棱飞走了。你猜她那边，耳朵一定是红的。']] },
    { l: '谢谢，我会一直戴着', aff: { ngoc: 1 }, lines: [['ngoc', '戴着就戴着，别到处给人看。'], ['ngoc', '……丢了要赔。']] }] },
  zhenList: { q: [['zhen', '十一个香客，有四个是从镇上失踪的人。全都在出事前，来山神庙上过香。'], ['zhen', '……你觉得，这说明什么？']], opts: [
    { l: '清虚道长有问题', aff: { zhen: 1 }, set: { zhenSuspect: 1 }, lines: [['zhen', '没有证据的话，别乱说。'], ['zhen', '……但我也是这么想的。'], ['zhen', '这份名单我收着。总有一天，用得上。']] },
    { l: '山神庙香火旺，碰巧罢了', lines: [['zhen', '碰巧？四个人，全是碰巧？'], ['zhen', '你啊，心太软。干不了捕快。'], ['narr', '她还是把名单仔细折好，收进了怀里。']] }] },
  huPersuade: { q: [['xiaohu', '我不走！它们没有娘！我走了，它们会难过的！']], opts: [
    { l: '（掏出雷婶给的麦芽糖）你娘让我带给你的', need: 'maiya', aff: {}, set: { huSweet: 1 }, lines: [['narr', '小虎盯着那块麦芽糖，嘴一瘪，眼泪先下来了。'], ['xiaohu', '……娘有没有骂我？'], ['me', '她说，回来再骂。'], ['xiaohu', '……那我回去挨骂。'], ['narr', '他把麦芽糖掰成四块，三块塞给了狼崽。']],
      nlines: [['me', '你娘在家里哭了一天。'], ['xiaohu', '……你骗人。我娘从来不哭。'], ['narr', '他嘴上这么说，手里的狼崽却慢慢放下了。'], ['xiaohu', '……就回去看一眼。']] },
    { l: '你爹的腿，是为了押镖受的伤', set: { huDad: 1 }, lines: [['xiaohu', '……我知道。'], ['xiaohu', '我就是想给他做个狐狸皮围脖。冬天他的腿就不疼了。'], ['me', '你爹现在不怕腿疼。他怕你回不去。'], ['narr', '小虎低着头，揪着狼崽的耳朵，揪了很久。'], ['xiaohu', '……好吧。']] },
    { l: '我答应你，以后带你回来看它们', aff: { zhen: 1 }, set: { huPromise: 1 }, lines: [['xiaohu', '真的？拉钩！'], ['narr', '小虎伸出沾满泥的小拇指。你勾了上去。'], ['zhen', '……答应小孩的事，可是要做到的。'], ['me', '我知道。']] }] },
  agui2: { q: [['agui', '恩人！昨晚要不是你守着门，我这条命就交代在这儿了。'], ['agui', '我一个砍柴的，没什么能给你的……']], opts: [
    { l: '不用谢，你腿还伤着，早点回家', aff: { zhen: 1 }, lines: [['agui', '……好人。你是好人。'], ['agui', '道长说我这腿还得养几天，等好了，我就回镇上。'], ['narr', '他说这话的时候，清虚道长正在门口，背对着你们，一动不动。']] },
    { l: '你在林子里砍了二十年柴，见过奇怪的事吗？', aff: { zhen: 1 }, lines: [['agui', '奇怪的事？'], ['agui', '……这两年，夜里常看见一队人，排着队往古树那边走。不说话，也不打灯笼。'], ['agui', '我以为是鬼，没敢跟。'], ['zhen', '（低声）记下了。']] }] },
});

CAMPTALK[2] = [
  { id: 'n2amulet', t: 'Ngoc 缝的护身符', at: ['linfire', 'hutfire', 'templefire'], when: S => mPast(S, 'm8'), lines: [
    ['narr', '篝火边，一只纸鹤扑棱棱落在你膝上。是 Ngoc 的传音符。'],
    ['ngoc', '（传音）喂。你包袱最底下，我塞了个东西。'],
    ['narr', '你翻出来一看，是个红布缝的护身符，针脚歪歪扭扭，上面绣着一个「安」字。'],
  ], choice: 'amulet' },
  { id: 'z2laosun', t: '打了三十年更的人', at: ['templefire', 'gushufire'], when: S => !!S.flags.zhenFollow, lines: [
    ['narr', '珍姑娘把老孙的更锣擦得干干净净，放在火边。'],
    ['zhen', '老孙打了三十年更，从没误过一个时辰。'],
    ['zhen', '我小时候怕黑，我哥就带我去更房找老孙。他让我敲锣，说锣一响，鬼就不敢来。'],
    ['zhen', '……锣在这儿。人呢？'],
  ], aff: { zhen: 1 } },
  { id: 'z2night', t: '珍姑娘守夜', at: ['gushufire', 'langfire', 'shuxinfire'], when: S => !!S.flags.zhenFollow && mPast(S, 'm20'), lines: [
    ['narr', '珍姑娘抱着刀守夜。火光里，她的侧脸冷冰冰的。'],
    ['zhen', '那个道士救你的时候，手法太熟了。'],
    ['zhen', '吸阳气的钉子，他说替你镇着——他凭什么镇得住？'],
    ['me', '你在怀疑他。'],
    ['zhen', '我怀疑所有人。包括你。'],
    ['zhen', '……睡吧。我守着。'],
  ], aff: { zhen: 1 } },
  { id: 'g2story', t: '耿伯的旧事', at: ['hutfire'], when: S => sDone(S, 'S7') || mPast(S, 'm12'), lines: [
    ['narr', '耿伯往火塘里添了根柴，半天没说话。'],
    ['geng', '我那口子走的那年冬天，我天天进山。下套子，掏窝，什么来钱快干什么。'],
    ['geng', '药铺的药，一副就是一两银子。'],
    ['geng', '……后来药也没救回来。'],
    ['narr', '墙上那串狼牙，在火光里一晃一晃。'],
  ] },
];

