QUIZ.cangtou = [
  { q: [['long', '这方子是一首藏头诗。「蛛丝难缚凌云志」——第一句，藏的是什么？']],
    opts: [['蛛', true, [['long', '正是。蛛——蛛网下的草。']]], ['丝', false, [['long', '兄台，藏头诗，藏的是头。']]], ['志', false, [['long', '那是藏尾了。']]]] },
  { q: [['long', '「潭深自有清凉处」——第二味药？']],
    opts: [['深', false, [['long', '再想想，头一个字。']]], ['潭', true, [['long', '潭——毒水潭边。']]], ['凉', false, [['long', '凉是药性，不是药名。']]]] },
  { q: [['long', '「老树逢春又一年」——第三味？']],
    opts: [['老', true, [['long', '老树，最老的那棵树底下！'], ['long', '蛛网下、毒潭边、老树底——三处的草合在一起，便是解蛛毒丹。']]], ['春', false, [['long', '兄台，是头一个字。']]], ['年', false, [['long', '……兄台故意的吧。']]]] }];

Object.assign(CHOICES, {
  wangquezi: { q: [['huoji3', '三个月！整整三个月没发工钱！'], ['huoji3', '他康胖子天天吃香喝辣，我们喝西北风？今天不给钱，我就把醉仙楼的招牌砸了！']], opts: [
    { l: '砸了招牌，你们以后在哪儿干活？', aff: { kang: 1 }, lines: [['huoji3', '……'], ['huoji3', '我在醉仙楼干了十二年。十二年！'], ['huoji3', '……招牌是我刷的漆。'], ['narr', '王瘸子把手里的板凳放下了。']] },
    { l: '我帮你们把钱要回来', aff: { zhen: 1 }, lines: [['huoji3', '你？你一个从坟里爬出来的，凭什么？'], ['zhen', '凭我在旁边看着。'], ['huoji3', '……行。珍捕头作保，我信一回。']] }] },
  pretty: { q: [['spiderq', '小哥哥，本宫问你一句——'], ['spiderq', '我和那只狐狸精，谁好看？']], opts: [
    { l: '当然是娘娘好看', aff: { ngoc: -1 }, set: { pretty: 1, bossSlow: 1 }, lines: [['spiderq', '嘻嘻……嘴真甜。'], ['spiderq', '那本宫就让你先出手。'], ['narr', '（远在青石镇的药铺里，Ngoc 打了个喷嚏。）']] },
    { l: '狐狸好看', aff: { ngoc: 2 }, set: { bossRage: 1 }, lines: [['spiderq', '……你说什么？'], ['spiderq', '你说什么？！'], ['narr', '蜘蛛娘娘的八只眼睛同时变红了。'], ['spiderq', '又是她！三百年了，又是她！！']] },
    { l: '……什么狐狸精？', lines: [['spiderq', '装傻？'], ['spiderq', '你身上全是她的味道。'], ['spiderq', '……她居然还没死。']] }] },
  nail3: { q: [['daotong', '小道长奉师父之命，来取金之钉。师父说，此物凶险，替施主镇着。'], ['zhen', '（低声）别给。']], opts: [
    { l: '给他', aff: { zhen: -1, ngoc: -2 }, set: { nail3Given: 1 }, lines: [['daotong', '多谢施主。'], ['narr', '小道童把钉子揣进袖子，一溜烟跑了。'], ['zhen', '……你会后悔的。']] },
    { l: '不给，我自己收着', aff: { zhen: 1, ngoc: 1 }, set: { nail3Kept: 1 }, lines: [['daotong', '这……师父会生气的。'], ['me', '让他自己来拿。'], ['narr', '小道童没再说什么，鞠了个躬走了。'], ['zhen', '这才像话。'], ['zhen', '……不过，宝物这种东西，迟早会回到想要它的人手里。你小心点。']] }] },
  taste: { q: [['kang', '尝尝！新菜，「松茸烩肘子」！'], ['kang', '怎么样？好不好吃？']], opts: [
    { l: '说实话：太咸了', aff: { kang: 1 }, set: { tasteHonest: 1 }, lines: [['kang', '……咸？'], ['narr', '康总管自己尝了一口，脸皱成一团。'], ['kang', '还真是！好兄弟，就你肯说实话！后厨！重做！']] },
    { l: '好吃！天下第一！', lines: [['kang', '哈哈哈！我就知道！'], ['narr', '他高高兴兴地端走了。那盘菜咸得你喝了三碗水。']] }] },
  seats: { q: [['liu', '座次嘛，原则上要按身份排。刘某坐上首，雷镖头坐门口——'], ['lei', '凭什么老子坐门口？！']], opts: [
    { l: '帮刘师傅说话', aff: { liu: 1 }, lines: [['liu', '你看，年轻人懂规矩。'], ['lei', '好，好。等会儿划拳，你给我等着。']] },
    { l: '帮雷镖头说话', lines: [['lei', '够意思！'], ['liu', '……这个问题，我们会后再议。']] },
    { l: '摆圆桌，不分上下', need: 'roundTable', aff: { liu: 1 }, lines: [['me', '龙道长说过，古人宴饮，圆席为和。'], ['liu', '……圆席为和。有出处，有依据。'], ['lei', '圆桌好！谁也别坐门口！'], ['narr', '两个人难得同时点了头。']],
      nlines: [['me', '要不……摆个圆桌？'], ['liu', '圆桌？有什么讲究吗？'], ['me', '……没什么讲究。'], ['liu', '没讲究的事，原则上不办。'], ['narr', '最后还是按刘师傅的排法。雷老虎坐在门口，一晚上瞪着你。']] }] },
  zhenDrunk: { q: [['zhen', '我哥……珍大……'], ['zhen', '他做的红烧肉，比这胖子做的好吃一百倍。'], ['kang', '……这个我不反驳。'], ['zhen', '……喂。你说，他还活着吗？']], opts: [
    { l: '我帮你找到他', aff: { zhen: 2 }, lines: [['zhen', '……'], ['zhen', '说话算话。'], ['narr', '她把脸埋进胳膊里。你听见她很小声地说了一句「谢谢」。']] },
    { l: '（陪她坐着，什么也不说）', aff: { zhen: 1 }, lines: [['narr', '你陪她坐着。她一碗一碗地喝，你一碗一碗地给她倒。'], ['zhen', '……你这人，倒是安静。']] }] },
  roof: { q: [['ngoc', '……喂。'], ['ngoc', '要是有人……等了你很久很久。'], ['ngoc', '久到她自己都忘了在等什么。'], ['ngoc', '你会怎么办？']], opts: [
    { l: '那我一定去找她', aff: { ngoc: 2 }, lines: [['narr', 'Ngoc 没说话。她把酒坛子抱在怀里，看了你很久。'], ['ngoc', '……傻子。']] },
    { l: '让她别等了', lines: [['ngoc', '……'], ['ngoc', '……傻子。'], ['narr', '她仰头喝了一大口。']] },
    { l: '你在说谁？', aff: { ngoc: 1 }, lines: [['ngoc', '说书里的人。'], ['ngoc', '……你管那么多干嘛。']] }] },
});

CAMPTALK[3] = [
  { id: 'n3sew', t: '扎破的手指', at: ['towncamp'], when: S => sDone(S, 'S1'), lines: [
    ['narr', '药铺后院，Ngoc 在灯下缝东西。针太粗，皮太硬。'],
    ['ngoc', '嘶——'],
    ['me', '扎到手了？'],
    ['ngoc', '没有。'],
    ['narr', '她把手指含在嘴里，含糊不清地说：'],
    ['ngoc', '……穿上它，别再被什么东西缠住了。听见没有。'],
  ], aff: { ngoc: 1 } },
  { id: 'z3wood', t: '名单越来越长', at: ['cpfire', 'sjfire', 'dkfire'], when: S => !!S.flags.zhenFollow && mPast(S, 'm10'), lines: [
    ['zhen', '阿贵不见了。上回在山神庙，被清虚包扎腿的那个樵夫。'],
    ['zhen', '他媳妇说，道长让他「腿好了就去山上采药，采到了就给他治根」。'],
    ['zhen', '还有茶棚老板娘说的——白衣道士常带人上山，空手下来。'],
    ['zhen', '……我手上的名单，越来越长了。'],
  ], aff: { zhen: 1 } },
  { id: 'k3cocoon', t: '康总管的生意经', at: ['jianfire', 'psfire'], when: S => mPast(S, 'm14'), lines: [
    ['kang', '好兄弟，你知道我为什么做生意吗？'],
    ['kang', '我娘说，人这辈子，要么有钱，要么有人。'],
    ['kang', '我没本事有人，就想着先有钱。'],
    ['kang', '……可今天在茧子里吊着的时候，我想的不是钱。是醉仙楼那帮伙计。'],
    ['kang', '王瘸子刷了十二年的招牌。张小六他娘的药钱。李大嘴那门亲事……'],
    ['kang', '他们过年，得有钱回家啊。'],
  ], aff: { kang: 1 } },
  { id: 'l3letter', t: '茶棚的灯', at: ['cpfire'], when: S => sDone(S, 'S9'), lines: [
    ['narr', '茶棚的灯亮到很晚。老板娘坐在灶边，把那封只有一行字的回信看了一遍又一遍。'],
    ['laoban', '三十年前，他是县衙的师爷，我是山下卖茶的。'],
    ['laoban', '他说等他做完那本账，就来提亲。'],
    ['laoban', '账没做完，他跑了。……我在这山上，一等就是三十年。'],
    ['laoban', '「原则上同意」。呵。'],
  ], aff: { liu: 1 } },
];

