// ==================== 第六章 · 昆仑冰窟（主题：真相）  + 幕间三 · 三百年前的梦 ====================
// 主线：五块残碑 → 清虚「恰好」也想去 → Ngoc 的暖炉 → 珍姑娘同行 → 雪山道伏击 → 冰家村 → 族长「你身上有土气」→ 祠堂 → 族长的话 → 冰湖 → 冰下的妖兵 → 推冰块开冰门
//       → 冰壁三处 → 冰壁里的脸 → 冰窟里推冰块开殿门 → 玄冰子 → 真相 → 化雪 → 族长的托付 → 白云观「闭关了」→ 磨刀老头
// 幕间：饭篮 → 给五位师兄送饭 → 地动 → 白云子「我去拿法器」→ 山坡后面的草丛 → 第五个位置 → 九尾白狐 → 封印 → 醒来
