// 冰钓：钓上来的鱼，冰大娘要三条
W_MINI_RW.fish = (ch, win) => { if (ch !== 6 || !win) return ''; const S = wstate(6); S.pz.fish = (S.pz.fish || 0) + 1;
  const q = S.side.S10, need = q && q.st === 'on' && q.step === 0;
  if (Math.random() < 0.15) { const key = gemKey(RNG.pick(Object.keys(GEM_TYPES)), 1); addGem(key); return `剖开鱼肚子——里面有一颗${gemName(key)}！` + (need ? `（冰鱼 ${Math.min(3, S.pz.fish)}/3）` : ''); }
  if (need) return S.pz.fish >= 3 ? '三条冰鱼，够了。拿去给冰大娘。' : `冰鱼 ${S.pz.fish}/3`;
  SAVE.gold += 25; return '鱼拿去村里换了二十五两银子。'; };
// 打雪仗：赢了冰小雪，她就把秘密告诉你
W_MINI_RW.snowball = (ch, win) => { if (ch !== 6 || !win) return ''; const S = wstate(6);
  if (S.side.S9 && S.side.S9.st === 'on' && !S.flags.snowWin) { S.flags.snowWin = 1; return '冰小雪抹了一把脸上的雪：「……算你厉害！过来，告诉你个秘密。」'; }
  SAVE.gold += 30; return '孩子们凑了三十两碎银子「上贡」，求你明天还来。'; };
// 寒气：雪山道和雪原上，离火堆远了就一点点冻透；冻透了每走几步掉血
const g6ColdRate = (run) => (wkeys().xuexue ? 0.5 : 1) * (wkeys().huotan ? 0.6 : 1) * (run.food === 'yutang' ? 0.5 : 1);
const g6NearFire = (m, x, y) => Object.keys(m.pts).some(c => m.def.pts[c].t === 'camp' && m.pts[c].some(p => Math.abs(p.x - x) + Math.abs(p.y - y) <= 3));
const g6Now = () => typeof performance !== 'undefined' ? performance.now() : 0;
WNPC.m_qing = { idle: ['阿土，慢点走，别摔着。'] }; WNPC.m_jin = { idle: ['小阿土！'] }; WNPC.m_lie = { idle: ['看什么看！'] };
