// 第四章的隐藏熔炉：有避火珠才走得进去（第六章要的火种）
Object.assign(WMAPS[4].scenes.ronglu.pts, {
  h: { t: 'relic', key: 'huozhong', n: '隐藏熔炉', spr: 'fire', when: S => !!wkeys().bihuozhu,
    lines: [['narr', '岩浆里有一座小小的熔炉，炉火三百年没灭。'], ['narr', '你伸手进去，捧出一团不烫手的火。'], ['lieyangzi', '……小师弟，拿去。冻不着你。']] },
});

WQ[6] = {
  main: [
    // ---------- 序 · 第一次主动出发 ----------
    { id: 'm1', t: '五块残碑', d: '去书院找龙道长', goal: { talk: 'long' }, auto: true,
      lines: [
        ['long', '兄台！五块残碑，在下终于拼起来了！'],
        ['narr', '书院的地上铺满了拓片，龙道长跪在中间，衣服上全是墨。'],
        ['long', '碑的最后一句是：「水之钉，冻于昆仑。守钉者，未死。」'],
        ['long', '……守钉的人，还活着？三百年了？'],
        ['me', '我要去昆仑。'],
        ['narr', '这是你第一次，自己决定要去哪儿。'],
        ['narr', '你想当面问问那个守钉的人：这些钉子，到底是锁，还是钥匙。'],
      ], rw: { xp: 0.2 } },
    { id: 'm2', t: '「恰好」', d: '清虚道长在告示板前等你', goal: { talk: 'qingxu' }, choice: 'qxRefuse',
      lines: [['narr', '你刚走出书院，就看见清虚站在告示板前，好像等了很久。']], rw: { xp: 0.1 } },
    { id: 'm3', t: '同行', d: '出发前，去药铺跟 Ngoc 说一声，再去捕快房找珍姑娘（{n}/2）', goal: { talks: ['ngoc', 'zhen'] },
      tl: {
        ngoc: [['ngoc', '昆仑？'], ['ngoc', '……我去不了。身子还虚。'], ['narr', '她往你怀里塞了个铜暖炉，烫得你一哆嗦。'], ['ngoc', '冻坏了，没人付药钱。'], ['me', '暖炉是空的？'], ['ngoc', '炭你自己找。昆仑山里有火精炭，冰窟的地热口边上。'], ['ngoc', '雪山上的风是吃人的。走一阵就找火堆烤一烤，别逞强。'], ['ngoc', '……早点回来。']],
        zhen: [['zhen', '昆仑？我跟你去。'], ['zhen', '我查到一件事：白云观每年都往昆仑山上送香火。送了不知道多少年。'], ['zhen', '一个山下的道观，给山上送香火——给谁送？'], ['narr', '（珍姑娘和你同行。）']],
      },
      set: { zhenFollow: 1, kunlunOpen: 1 }, aff: { ngoc: 1, zhen: 1 }, rw: { xp: 0.3 } },
    // ---------- 第一幕 · 雪山道与冰家村 ----------
    { id: 'm4', t: '雪坳', d: '上昆仑。雪山道半路有一处雪坳', hint: '雪山道中间。', area: 'xueshan', goal: { reach: 'xuekou' }, mark: 'xuekou',
      waves: [{ kind: 'battle', mon: 1, n: 3, lv: 21 }, { kind: 'battle', mon: 1, n: 3, lv: 22, mix: [1, 4] }, { kind: 'elite', mon: 3, lv: 22, name: '雪人' }],
      lines: [['narr', '雪坳里静得出奇。'], ['narr', '然后，四面八方的雪堆一起动了起来——是狼。']],
      between: [[['zhen', '它们一直跟着我们！']], [['zhen', '后面那个大家伙是什么？！']]],
      after: [['zhen', '……雪原上的狼，都这么饿吗？'], ['narr', '雪坳另一头，有炊烟。']], rw: { xp: 0.5 } },
    { id: 'm5', t: '冰家村', d: '去有炊烟的地方', hint: '雪山道东边。', area: 'xueshan', goal: { enter: 'bingcun' }, mark: 'bcfire',
      lines: [['narr', '一个小村子，十几户人家，房子都是石头垒的。家家户户门口挂着冰灯。'], ['narr', '村里的人都在看你。一个老人拄着拐杖，慢慢走了过来。']], rw: { xp: 0.3 } },
    { id: 'm6', t: '冰家族长', d: '和村里的老人说话', goal: { talk: 'zuzhang' },
      lines: [
        ['zuzhang', '外乡人？'],
        ['narr', '老族长围着你转了一圈，鼻子使劲嗅了嗅。'],
        ['zuzhang', '……你身上，有土气。'],
        ['zuzhang', '冰家全村，都姓冰。祖上是个道士，三百年前上山，没下来。'],
        ['zuzhang', '他留了一句话：「若有人带着土气上山，放他进去。」'],
        ['zuzhang', '我们冰家，等了三百年。'],
        ['zhen', '……放他进哪儿去？'],
        ['zuzhang', '冰湖。冰湖后面，是冰窟。冰窟后面——'],
        ['zuzhang', '你先去祠堂看看。看完了，我再告诉你。'],
      ], rw: { xp: 0.3 } },
    { id: 'm7', t: '祠堂', d: '去冰家的祠堂看看（{n}/2）', hint: '村子北边的小屋（{n}/2）', area: 'bingcun', goal: { clue: 'citang', n: 2 }, mark: 'clue:citang',
      after: [['zhen', '白云观的香。'], ['zhen', '白云观往昆仑送香火，送到了冰家祠堂。'], ['zhen', '给一个三百年前上山没下来的道士上香。'], ['narr', '你们对视了一眼，谁也没说话。']], rw: { xp: 0.3 } },
    { id: 'm8', t: '族长的话', d: '回去找族长', goal: { talk: 'zuzhang' },
      lines: [
        ['zuzhang', '看完了？'],
        ['zuzhang', '冰湖上有一道冰门，三百年没开过。门前有冰眼，冰块推上去，门就开。'],
        ['zuzhang', '先祖说，冰门只给带土气的人开。'],
        ['zuzhang', '……冰湖上冻着的东西，你看了别怕。'],
        ['zuzhang', '它们动不了。'],
        ['narr', '（冰湖的路开了。冰块推不回来的话，敲一敲墙角的冰锥，冰块会回到原处。）'],
      ], set: { binghuOpen: 1 }, rw: { xp: 0.2 } },
    // ---------- 第二幕 · 冰湖与冰窟 ----------
    { id: 'm9', t: '冰湖', d: '去村子北边的冰湖，看看冰面下面', hint: '冰家村北边，冰湖岸边。', area: 'binghu', goal: { clue: 'bingxia', n: 1 }, mark: 'clue:bingxia',
      after: [['narr', '湖的东边，有一道冰门，门前有一间冰屋。'], ['zhen', '族长说的冰门……就是那个？']], rw: { xp: 0.4 } },
    { id: 'm10', t: '冰门', d: '把冰块推到冰眼上，打开冰门，进冰窟', hint: '冰门前的屋子里。中间的冰墙只有一个口，冰块得从口里过去。', area: 'binghu', goal: { enter: 'bingku' }, mark: 'bkfire',
      lines: [['narr', '冰窟里的冰壁像一面一面镜子。每一面里面，都封着东西。']], rw: { xp: 0.5 } },
    { id: 'm11', t: '冰壁', d: '在冰窟里看看冰壁（{n}/3）', hint: '冰窟四周的冰壁里封着东西（{n}/3）', area: 'bingku', goal: { clue: 'bingbi', n: 3 }, mark: 'clue:bingbi', rw: { xp: 0.4 } },
    { id: 'm12', t: '那张脸', d: '珍姑娘有话要说', goal: { talk: 'zhen' }, choice: 'face6',
      lines: [['narr', '珍姑娘一直站在那面冰壁前，没有走。']],
      after: [['narr', '冰窟北边，一道殿门被冰封着。门前的冰湖里，有两个冰眼。']], rw: { xp: 0.2 } },
    { id: 'm13', t: '冰封殿', d: '把两块冰块滑到冰眼上，打开冰封殿的门', hint: '冰块推到冰面上会一直滑，撞到冰柱才停。想好了再推。', area: 'bingku', goal: { enter: 'bingdian' }, mark: 'bdfire',
      lines: [['narr', '冰封殿正中，一个人坐在冰座上，浑身结满了霜。'], ['narr', '他睁开眼睛。眼睛是蓝的。']], rw: { xp: 0.5 } },
    // ---------- 第三幕 · 玄冰子 ----------
    { id: 'm14', t: '玄冰子', d: '冰座上的人站了起来', goal: { fight: 'boss6' }, mark: 'boss6',
      lines: [['xuanbingzi', '……白云子。'], ['xuanbingzi', '白云子！你还有脸回来！'], ['me', '我不是——'], ['xuanbingzi', '三百年了！拔剑！']],
      after: [
        ['narr', '玄冰子的剑停在你脖子前，一寸都没再往前。'],
        ['xuanbingzi', '……不对。'],
        ['xuanbingzi', '白云子的剑，没你这么笨。'],
        ['narr', '他盯着你的脸，看了很久很久。'],
        ['xuanbingzi', '……小师弟？'],
        ['xuanbingzi', '你回来了。'],
      ], set: { bossDead: 1 }, rw: { xp: 0.8, item: 'rare' } },
    // ---------- 第四幕 · 真相 ----------
    { id: 'm15', t: '真相', d: '玄冰子有话要说', goal: { talk: 'xuanbingzi' },
      lines: [
        ['narr', '玄冰子身上的冰一片一片往下掉。他在冰座上坐下，指了指旁边的位置。'],
        ['xuanbingzi', '坐。'],
        ['xuanbingzi', '我们五个师兄弟：青木子、金不换、烈阳子、我，还有白云子。'],
        ['xuanbingzi', '你不是五个之一。你是送饭的。阿土。十五岁。'],
        ['xuanbingzi', '你送了三年饭。每天一篮，一个人一个饭团，烈阳子要两个。'],
        ['xuanbingzi', '那天魔尊破土，五个人要站五个位置。白云子说「我去拿法器」，就再也没回来。'],
        ['xuanbingzi', '你把饭篮一扔，站上了第五个位置。'],
        ['xuanbingzi', '我们喊你下来。你说：「我送了三年饭，阵法我都背下来了。」'],
        ['narr', '你张了张嘴，什么都说不出来。'],
        ['xuanbingzi', '你魂最弱，钉子最先裂开。所以你最先醒。'],
        ['me', '……钉子，是锁，还是钥匙？'],
        ['xuanbingzi', '一根钉子，是锁。五根钉子凑在一起——就是钥匙。'],
        ['xuanbingzi', '有人把五根钉子拿齐，就能把门打开。'],
        ['xuanbingzi', '小师弟，记住：白云子最会装好人。他要是还活着——'],
        ['xuanbingzi', '一定在「帮」你找钉子。'],
        ['narr', '你整个人僵住了。'],
        ['narr', '木之钉。金之钉。火之钉。'],
        ['narr', '「贫道替施主镇着。」'],
      ], rw: { xp: 0.3 } },
    { id: 'm16', t: '化雪', d: '玄冰子撑不住了', goal: { talk: 'xuanbingzi' },
      lines: S => [
        ['xuanbingzi', '我在这儿等了三百年。等白云子回来，给我一个交代。'],
        ['xuanbingzi', '……等来的是你。也好。'],
        ['narr', '他的手开始变成雪，一点一点往下掉。'],
        ...((wPast(3, 'nail3Kept') || wPast(4, 'nail4Kept')) ? [['xuanbingzi', '你身上有钉子的味道。你没全交出去？'], ['xuanbingzi', '……好。比我们五个都聪明。']] : [['xuanbingzi', '你身上，一根钉子都没有。'], ['xuanbingzi', '……全给他了？'], ['narr', '他没有骂你。他只是叹了一口气。']]),
        ['xuanbingzi', '水之钉，在我心口。拿去。'],
        ['xuanbingzi', '这回……别再弄丢了。小师弟。'],
        ['narr', '玄冰子笑了笑，身子化成了一阵雪。'],
        ['narr', '雪落下来，落在一根蓝色的钉子上。'],
        ['narr', '（得到「水之钉」。）'],
      ], after: [['narr', '「咔——」'], ['narr', '冰座裂开了。整座冰封殿，跟着它的主人一起，开始往下塌。'], ['zhen', '快跑！'], ['narr', '（一路跑回冰湖！地上出现红圈的地方，冰锥要砸下来了。步数用完之前跑不出去，就会被埋回殿门口。）']], set: { esc6: 1 }, rw: { xp: 0.3, key: 'shuiding' } },
    { id: 'm17', t: '冰崩', d: '冰封殿要塌了！一路跑回冰湖', hint: '出殿门，穿过冰窟，往南跑回冰湖。地上出现红圈的地方，冰锥要砸下来了——躲开。', goal: { enter: 'binghu' }, mark: 'bhfire', set: { escaped: 1 },
      lines: [['narr', '你一脚踏上冰湖的冰面，身后传来一声闷响。'], ['narr', '回头看——冰窟的洞口塌了，冰封殿埋进了山肚子里。'], ['zhen', '……他一个人在里面待了三百年。'], ['zhen', '现在，连门都没有了。'], ['narr', '你攥着水之钉，站了很久。']], rw: { xp: 0.4 } },
    // ---------- 尾声 ----------
    { id: 'm18', t: '族长的托付', d: '回冰家村，告诉族长', goal: { talk: 'zuzhang' },
      lines: [
        ['zuzhang', '……他走了？'],
        ['narr', '老族长对着冰封殿的方向，跪下磕了三个头。全村的人都跪下了。'],
        ['zuzhang', '这是先祖的佩剑。他说过，山下还有一支后人。'],
        ['zuzhang', '劳烦你，带给他们。'],
        ['narr', '你接过剑。剑柄上缠着一根褪色的红绳。'],
        ['narr', '你想起来了。'],
        ['narr', '你的名字。'],
        ['me', '……阿土。'],
        ['zhen', '……什么？'],
        ['me', '我叫阿土。'],
      ], aff: { zhen: 1 }, rw: { xp: 0.3, item: 'rare', slot: 'weapon' } },
    { id: 'm19', t: '闭关', d: '回青石镇，直奔白云观——镇上有个小道童', goal: { talk: 'daotong' },
      lines: [
        ['narr', '你一路没停，直奔白云观。山门口，那个小道童拦住了你。'],
        ['daotong', '施主，师父闭关了。谁也不见。'],
        ['me', '他闭关多久？'],
        ['daotong', '师父说……等到钉子齐了，就出关。'],
        ['narr', '你攥紧了怀里的水之钉。'],
        ['narr', '这一次，你不会交出去。'],
        ['zhen', '……镇上那个磨刀的老头，你答应族长要把剑带给他。'],
      ], set: { nail6Kept: 1 }, rw: { xp: 0.2 } },
    { id: 'm20', t: '磨刀老头', d: '把玄冰子的佩剑交给镇上那个不说话的磨刀老头', goal: { talk: 'modao' },
      lines: [
        ['narr', '你把剑递过去。磨刀老头看见剑柄上的红绳，手里的磨刀石掉在了地上。'],
        ['modao', '……冰家。'],
        ['narr', '这是他第一次开口。镇上的人都说他是哑巴。'],
        ['modao', '我家祖训，只有一句。'],
        ['modao', '「欠一个送饭的孩子一条命。」'],
        ['narr', '他看着你，看了很久。'],
        ['modao', '……你来讨了？'],
        ['narr', '那天夜里，你发起了高烧。'],
        ['narr', '你做了一个很长很长的梦。'],
      ], set: { zhenFollow: 0 }, tele: ['meng', 'f', 'mengfire'], rw: { xp: 0.2 } },
    // ---------- 幕间三 · 三百年前的梦 ----------
    { id: 'i1', t: '幕间·饭篮', d: '你是十五岁的阿土。去山脚的小屋拿饭篮', hint: '山脚的小屋。', goal: { get: 'fanlan' }, mark: 'fanlan',
      lines: [['narr', '饭篮很沉。五个饭团，一个给青木子，一个给金不换，两个给烈阳子，一个给玄冰子，一个给白云子。'], ['narr', '……六个。你数了三遍，还是六个。'], ['narr', '多出来的那个，是烈阳子昨天说的：「明天多带一个，给你自己。」']], rw: { xp: 0.1 } },
    { id: 'i2', t: '送饭', d: '给山坡上的五位师兄送饭（{n}/5）', goal: { talks: ['m_qing', 'm_jin', 'm_lie', 'm_xuan', 'm_bai'] },
      tl: {
        m_qing: [['m_qing', '阿土来啦？'], ['narr', '青木子摸了摸你的头，接过一个饭团。'], ['m_qing', '今天的饭团有点咸。……好吃。'], ['m_qing', '你脸上有灰。来，擦擦。']],
        m_jin: [['m_jin', '小阿土！来，师兄给你的！'], ['narr', '他往你手里塞了一块碎银子。你推回去。'], ['m_jin', '哈哈哈！又不要！你这孩子，跟我小时候一模一样！'], ['m_jin', '钱可以不要。命要留着。']],
        m_lie: [['m_lie', '慢！慢死了！老子都饿扁了！'], ['narr', '他一口吞了两个饭团，看了看篮子里多出来的那个。'], ['m_lie', '……那个是你的。吃了。'], ['m_lie', '看什么看！吃！瘦得跟猴似的！']],
        m_xuan: [['m_xuan', '坐。'], ['narr', '玄冰子把自己的蒲团让给你，自己坐在冰凉的石头上。'], ['m_xuan', '你走了一路，歇一歇。'], ['m_xuan', '……阵法背得怎么样了？'], ['atu', '背熟了。五个位置，我闭着眼睛都能走。'], ['m_xuan', '背熟了也别上去。那不是你的位置。']],
        m_bai: [['m_bai', '阿土，来，师兄给你算一卦。'], ['narr', '白云子掐着手指，算了很久，脸色一点一点白了。'], ['m_bai', '……大凶。'], ['m_bai', '今天，有人要死。'], ['narr', '他没有接你的饭团。']],
      },
      lines: [['narr', '饭篮空了。你坐在山坡上，看着五位师兄。'], ['narr', '天边的云，是红的。']], rw: { xp: 0.2 } },
    { id: 'i3', t: '地动', d: '地动了！冲到山坡正中', hint: '山坡正中。', goal: { reach: 'didong' }, mark: 'didong',
      waves: [{ kind: 'battle', mon: 0, n: 3, lv: 22 }, { kind: 'battle', mon: 0, n: 3, lv: 23, mix: [0, 5] }],
      lines: [['narr', '大地裂开了。一股黑气冲天而起，黑气里伸出无数只手，手里握着刀。'], ['m_qing', '魔尊破土了！五个人，各就各位！'], ['m_lie', '阿土！躲起来！']],
      between: [[['m_lie', '还有！地底下还在往外爬！']]],
      after: [['narr', '妖兵退了一波。地底下的黑气越来越浓。']], rw: { xp: 0.3 } },
    { id: 'i4', t: '白云子', d: '白云子在发抖', goal: { talk: 'm_bai' },
      lines: [['m_bai', '……法器。'], ['m_bai', '我的法器忘在山下了。我、我去拿法器！'], ['m_xuan', '白云子！阵就差你一个！'], ['m_bai', '马上回来！马上！'], ['narr', '白云子转身就跑。'], ['narr', '他跑得很快，一下就不见了。'], ['narr', '他没有回来。']],
      rw: { xp: 0.2 } },
    { id: 'i5', t: '山坡后面', d: '山坡后面好像有动静', hint: '东北边的乱石后面。', goal: { clue: 'caocong', n: 1 }, mark: 'clue:caocong', rw: { xp: 0.1 } },
    { id: 'i6', t: '第五个位置', d: '阵法缺一个人。站上第五个位置', hint: '山坡正中，五个位置空着一个。', goal: { reach: 'wuwei' }, mark: 'wuwei',
      lines: [
        ['m_lie', '白云子跑了！阵缺一角！'],
        ['narr', '你把饭篮一扔，跑上了第五个位置。'],
        ['m_xuan', '阿土！下来！你不在名单上！'],
        ['atu', '我送了三年饭，阵法我都背下来了！'],
        ['m_jin', '……傻孩子。'],
        ['m_qing', '阿土，站稳了。钉子在，人就在。'],
        ['narr', '五道光柱冲天而起。'],
      ], rw: { xp: 0.2 } },
    { id: 'i7', t: '九尾白狐', d: '一只白狐狸从光里走了出来', goal: { talk: 'jiuwei' },
      lines: [
        ['jiuwei', '……你还是个孩子。'],
        ['atu', '我送了三年饭。'],
        ['jiuwei', '……'],
        ['jiuwei', '五根钉子，镇不住它。还差一把锁。'],
        ['narr', '白狐吐出一颗发光的珠子——她的狐丹。'],
        ['jiuwei', '我用狐丹锁住它。你们五个，是钉子。'],
        ['atu', '那你呢？'],
        ['jiuwei', '我守着。'],
        ['atu', '……等我回来。'],
        ['jiuwei', '……'],
        ['jiuwei', '我等你。'],
      ], rw: { xp: 0.2 } },
    { id: 'i8', t: '封印', d: '魔尊从地底爬了出来', goal: { fight: 'mozunying' }, mark: 'mozunying',
      lines: [['narr', '黑气凝成一个巨大的影子，影子里睁开了两只眼睛。'], ['mozun', '……一个送饭的？'], ['mozun', '也想钉住我？']],
      after: [
        ['narr', '你打不过它。没有人打得过它。'],
        ['narr', '可你站在第五个位置上，一步都没退。'],
        ['narr', '狐丹落进阵眼。五根钉子同时亮了。'],
        ['narr', '你觉得自己的魂，被一根钉子，一寸一寸钉进了地里。'],
        ['narr', '最后看见的，是白狐的眼睛。'],
        ['narr', '她在哭。'],
      ], tele: ['town', 'f', 'towncamp'], rw: { xp: 0.3 } },
    { id: 'i9', t: '醒来', d: '你醒了', goal: { talk: 'ngoc' }, choice: 'wake6', final: true,
      lines: [['narr', '你睁开眼睛。药铺后院，窗外天刚亮。']], rw: { xp: 0.3 } },
  ],
  side: [
    { id: 'S1', t: '暖玉', giver: 'zuzhang', when: S => mPast(S, 'm6'),
      offer: [['zuzhang', '冰家有块暖玉，祖上传下来的。揣着它，冻不着。'], ['zuzhang', '上个月被一头雪狼叼走了，往雪原去了。'], ['zuzhang', '你要是找回来，就借你用。冰封殿里那位……冷得很。']],
      steps: [
        { d: '在雪原追踪雪狼（{n}/3）', hint: '雪原在冰家村东边。看看雪地上的痕迹（{n}/3）', area: 'xueyuan', goal: { clue: 'langji', n: 3 }, mark: 'clue:langji' },
        { d: '打倒雪狼王，夺回暖玉', hint: '雪原东南，最大的那头狼。', area: 'xueyuan', goal: { kill: 'langwang', n: 1 }, mark: 'mon:langwang' },
        { d: '回冰家村，狼群追着暖玉的味儿来了——守住冰窖（三波），和族长说话开始', goal: { waves: [
            { kind: 'battle', mon: 1, n: 3, lv: 22 }, { kind: 'battle', mon: 1, n: 4, lv: 23, mix: [1, 3] }, { kind: 'elite', mon: 3, lv: 24, name: '雪人头领' }] },
          lines: [['zuzhang', '暖玉回来了，狼群也跟来了！'], ['zuzhang', '冰窖里是全村过冬的粮食，帮我们守住！']],
          between: [[['zuzhang', '还有！']], [['zuzhang', '最大的来了！']]] },
        { d: '和族长说话', goal: { talk: 'zuzhang' }, lines: [['zuzhang', '暖玉，你拿着。'], ['zuzhang', '先祖说过：暖玉是给「送饭的孩子」留的。'], ['zuzhang', '……我一直不明白这句话。现在明白了。']] }],
      rw: { xp: 0.6, key: 'nuanyu' } },
    { id: 'S2', t: '烈阳子的火种', giver: 'long', when: S => mPast(S, 'm1'),
      offer: [['long', '兄台，冰封之物，最怕真火。'], ['long', '火焰窟的熔炉殿里，碑上记着烈阳子留了一座熔炉，炉火三百年不灭。'], ['long', '炉子在岩浆正中。兄台有避火珠，或许走得进去。']],
      steps: [{ d: '回火焰窟（出征页选第四章），用避火珠走进熔炉殿西南岩浆里的隐藏熔炉，取火种；再回来找龙道长', goal: { talk: 'long' }, needKey: 'huozhong',
        waitLines: [['long', '火种还没取到吗？在出征页选火焰窟，熔炉殿西南的岩浆里。']],
        lines: [['long', '这就是烈阳子的火？……暖的。'], ['long', '兄台，带着它上昆仑吧。']] }],
      aff: { long: 1 }, rw: { xp: 0.5 } },
    { id: 'S3', t: '火精炭暖炉', giver: 'zhen', when: S => mPast(S, 'm10'),
      offer: [['zhen', 'Ngoc 给你的暖炉，空的。'], ['zhen', '冰窟里有地热口，口子边上结着火精炭。装三块，炉子能烧三天三夜。']],
      steps: [
        { d: '在冰窟采火精炭（{n}/3）', hint: '冰窟里冒热气的地方（{n}/3）', area: 'bingku', goal: { herb: 'huotan', n: 3 }, mark: 'herb:huotan' },
        { d: '把炭装进暖炉，告诉珍姑娘', goal: { talk: 'zhen' }, lines: [['narr', '暖炉「呼」地烧了起来，烫得你差点扔了。'], ['zhen', '……她给你这东西的时候，手都冻红了。'], ['zhen', '你最好别辜负她。']] }],
      aff: { zhen: 1, ngoc: 1 }, rw: { xp: 0.4, key: 'huotan' } },
    { id: 'S4', t: '残碑·终', giver: 'long', when: S => mPast(S, 'm1'),
      offer: [['long', '五块碑拓全了，可在下总觉得少了什么。'], ['long', '县志上说，最后一块碑立在「冰封之所」。兄台若是到了，劳烦拓一张。']],
      steps: [
        { d: '在冰封殿找到最后一块碑，拓下来', hint: '冰封殿东南的墙角。', area: 'bingdian', goal: { rub: 'stele6' }, mark: 'stele6' },
        { d: '把拓片交给龙道长', goal: { talk: 'long' },
          lines: [['long', '「土位缺，有童子阿土代之，年十五，送饭三载。」'], ['long', '「白云子，不知所踪。」'], ['narr', '龙道长放下拓片，抬头看你。'], ['long', '阿土。'], ['long', '……兄台，你的名字，是不是叫阿土？'], ['narr', '你点了点头。'], ['long', '在下读了一辈子书。今天才知道，史书上最要紧的一行字，常常是没写的那一行。']] }],
      aff: { long: 2 }, rw: { xp: 0.5, item: 'rare' } },
    { id: 'S5', t: '白云观的账本', giver: 'zhen', when: S => mPast(S, 'm7'),
      offer: [['zhen', '祠堂里那炷香，是白云观的。'], ['zhen', '我要知道，白云观跟冰家村，有多少年的来往。']],
      steps: [
        { d: '在祠堂里找找香火簿', hint: '祠堂角落。', area: 'bingcun', goal: { clue: 'xianghuo', n: 1 }, mark: 'clue:xianghuo' },
        { d: '问冰家族长', goal: { talk: 'zuzhang' }, lines: [['zuzhang', '白云观？每年都派人来收香火钱。'], ['zuzhang', '收了……三百年了。'], ['zuzhang', '每次来的道士都不一样。可每一个都问同一句话：「冰封殿里那位，还活着吗？」'], ['narr', '珍姑娘的脸，一下子白了。']] },
        { d: '告诉珍姑娘', goal: { talk: 'zhen' }, lines: [['zhen', '……他一直在等。等玄冰子死。'], ['zhen', '玄冰子不死，水之钉他拿不走。'], ['zhen', '……我会记住的。']] }],
      aff: { zhen: 2 }, rw: { xp: 0.4, gold: 160 } },
    { id: 'S6', t: '雪莲', giver: 'kang', when: S => mPast(S, 'm3'),
      offer: [['kang', '昆仑的雪莲！一朵值千金！'], ['kang', '……我是说，炖汤特别鲜！']],
      steps: [
        { d: '采雪莲（{n}/3）', hint: '雪山道、冰家村、雪原都有（{n}/3）', area: 'xueyuan', goal: { herb: 'xuelian', n: 3 }, mark: 'herb:xuelian' },
        { d: '交给康总管', goal: { talk: 'kang' }, lines: [['kang', '雪莲炖鸡！美食图谱！'], ['kang', '好兄弟，你这一路，把天下的好东西都给我搜罗来了！'], ['narr', '（美食图谱：「雪莲炖鸡」。）']] }],
      aff: { kang: 1 }, rw: { xp: 0.3, gold: 200, flag: 'dish6' } },
    { id: 'S7', t: '雪原猎人', giver: 'lieren', when: S => mPast(S, 'm6'),
      offer: [['lieren', '我兄弟上个月进了雪原，没回来。'], ['lieren', '他叫冰木头。我叫冰石头。'], ['lieren', '……你要是碰见了，告诉我一声。活的死的都行。']],
      steps: [
        { d: '在雪原找找冰木头', hint: '雪原东边。', area: 'xueyuan', goal: { clue: 'lieshi', n: 1 }, mark: 'clue:lieshi' },
        { d: '回冰家村告诉猎人', goal: { talk: 'lieren' }, lines: [['narr', '你把弓递给他。'], ['lieren', '……'], ['lieren', '他抱着弓。'], ['lieren', '这张弓是我俩一起做的。他说，等打到雪狼王，就用狼皮给娘做件袄。'], ['narr', '猎人低着头，好一会儿。'], ['lieren', '这件狼皮袄，我做好了。本来是给娘的。'], ['lieren', '……你穿着吧。雪原上冻不着。']] }],
      rw: { xp: 0.4, item: 'rare', slot: 'chest' } },
    { id: 'S8', t: '通缉·大雪人', giver: 'zuzhang', when: S => mPast(S, 'm8'),
      offer: [['zuzhang', '雪山道上有个大雪人，堵了下山的路三个月了。'], ['zuzhang', '村里的盐快吃完了。']],
      steps: [
        { d: '在雪山道打倒大雪人', hint: '雪山道东南。', area: 'xueshan', goal: { kill: 'xueren', n: 1 }, mark: 'mon:xueren' },
        { d: '回冰家村告诉族长', goal: { talk: 'zuzhang' }, lines: [['zuzhang', '好！好！'], ['zuzhang', '冰家没什么好东西，这袋银子，是全村凑的。']] }],
      rw: { xp: 0.4, gold: 320 } },
    { id: 'S9', t: '打雪仗', giver: 'xiaoxue', when: S => mPast(S, 'm6'),
      offer: [['xiaoxue', '喂！外乡人！'], ['narr', '一个扎红头绳的小丫头叉着腰拦住你，身后躲着两个流鼻涕的小子。'], ['xiaoxue', '敢不敢跟我们打雪仗？'], ['xiaoxue', '你要是赢了，我告诉你一个秘密——连族长爷爷都不知道的秘密！'], ['zhen', '……你就陪她玩一把吧。']],
      steps: [
        { d: '在冰家村的雪堡跟冰小雪打雪仗，打赢她', hint: '冰家村南边，孩子们的雪堡。', goal: { talk: 'xiaoxue' }, needF: S => !!S.flags.snowWin, waitLines: [['xiaoxue', '来！谁先投降谁是小狗！']], waitMini: 'snowball',
          lines: [['xiaoxue', '……你过来，小声点。'], ['xiaoxue', '去年我偷偷跟着送香火的大人进了冰窟。'], ['xiaoxue', '冰窟东边的冰墙里头，有光！蓝蓝的，一闪一闪。'], ['xiaoxue', '我拿石头砸，砸不开。我爹说那是老祖宗的屋子，冰是拿火化的，小孩子不许去。'], ['xiaoxue', '……你有火吗？']] },
        { d: '去冰窟东边的冰墙，用火精炭暖炉化开它', hint: '冰窟东墙。没有暖炉化不开（支线「火精炭暖炉」）。', goal: { enter: 'bingshi' }, mark: 'bkfire' },
        { d: '在冰室里看看（推开里间的冰门，或者先看看石桌）', hint: '冰室里的石桌上压着东西。', goal: { clue: 'shouji', n: 1 }, mark: 'clue:shouji' },
        { d: '回冰家村告诉冰小雪', goal: { talk: 'xiaoxue' }, lines: [['xiaoxue', '真的有屋子？！里面有什么？金子？宝剑？'], ['me', '一只碗。'], ['xiaoxue', '……就一只碗？'], ['me', '嗯。很要紧的一只碗。'], ['xiaoxue', '……大人真奇怪。'], ['narr', '她想了想，从兜里掏出一颗冻硬的糖，塞给你。'], ['xiaoxue', '那这个也给你。也很要紧。']] }],
      aff: { zhen: 1 }, rw: { xp: 0.5, gold: 120 } },
    { id: 'S10', t: '冰鱼汤', giver: 'daniang', when: S => mPast(S, 'm6'),
      offer: [['daniang', '外乡人，脸都冻青了。'], ['daniang', '冰湖上有冰窟窿，底下的冰鱼最肥。你钓三条来，大娘给你炖一锅冰鱼汤。'], ['daniang', '喝一碗，骨头缝里都是热的——上雪原都不怕冻。']],
      steps: [
        { d: '去冰湖岸边的冰窟窿钓三条冰鱼', hint: '冰湖岸边有两个冰窟窿。浮漂沉到蓝色那段就提竿。', goal: { talk: 'daniang' }, needF: S => (S.pz.fish || 0) >= 3, mark: 'bhfire',
          waitLines: S => [['daniang', `冰鱼呢？才 ${Math.min(3, S.pz.fish || 0)} 条，不够一锅。`], ['daniang', '冰湖岸边，冰窟窿。浮漂一沉就提竿，别急。']],
          lines: [['daniang', '好鱼！'], ['narr', '冰大娘把鱼往锅里一扔，撒一把野葱，舀两勺雪水。火塘上「咕嘟咕嘟」地冒起了白气。'], ['daniang', '冰鱼汤的方子，就一句：鱼要活，火要旺，人要等。'], ['daniang', '我家老头子上山打猎，我就在火塘边炖着。他回来晚一个时辰，汤就熬白一分。'], ['daniang', '……后来汤熬得比雪还白，他也没回来。'], ['narr', '她把一碗汤推到你面前。'], ['daniang', '趁热喝。'], ['narr', '（美食图谱：「冰鱼汤」。在醉仙楼找康总管也能做。喝了它，雪地里寒气长得慢一半。）']] }],
      rw: { xp: 0.4, flag: 'dish6b', gold: 80, eat: 'yutang' } },
    { id: 'S11', t: '雪埋的猎屋', giver: 'lieren', when: S => sDone(S, 'S7'),
      offer: [['lieren', '……弓我收好了。'], ['lieren', '雪原东北角，我跟木头搭过一间猎屋。上个月雪崩，整个埋了。'], ['lieren', '木头的东西都在里面。我……一个人不敢去。'], ['lieren', '你帮我把它刨出来。里面有什么，你看着拿。']],
      steps: [
        { d: '去雪原东北角，把猎屋周围的积雪刨开（{n}/3）', hint: '雪原东北角，被雪埋住的小屋（{n}/3）', area: 'xueyuan', goal: { clue: 'liewu', n: 3 }, mark: 'clue:liewu' },
        { d: '屋里有东西在喘气——把它赶出来', hint: '猎屋门口。', area: 'xueyuan', goal: { kill: 'liewu', n: 1 }, mark: 'mon:liewu',
          lines: [['narr', '雪猿倒在门口。猎屋里，墙上挂着一张没做完的狼皮袄，针还别在袖口上。'], ['narr', '炕头压着一张纸，字写得歪歪扭扭：「哥，雪狼王我一个人去了。打到了，皮给娘做袄。你别跟来，你脚慢。」']] },
        { d: '回冰家村告诉冰石头', goal: { talk: 'lieren' }, lines: [['narr', '你把那张纸递给他。'], ['lieren', '……'], ['lieren', '他从小就嫌我脚慢。'], ['lieren', '我脚是慢。我要是快一点，就追上他了。'], ['narr', '冰石头把纸叠好，揣进怀里，跟弓放在一起。'], ['lieren', '屋里那张没做完的袄……你拿去。针脚是他的，剩下的我来缝。'], ['lieren', '以后进雪原，穿着它。就当他陪你走一段。']] }],
      rw: { xp: 0.5, item: 'set' } },
  ],
};

