WQ[7] = {
  main: [
    // ---------- 序 · 被支开 ----------
    { id: 'm1', t: '出关', d: '清虚道长「出关」了，登门拜访', goal: { talk: 'qingxu' }, auto: true, choice: 'qx7',
      lines: [
        ['narr', '中元节前三天。你正在药铺后院劈柴，清虚道长推门进来了。'],
        ['qingxu', '施主，贫道出关了。'],
        ['narr', '他笑得和平时一模一样。你攥着柴刀的手，紧了一下。'],
        ['qingxu', '贫道闭关时，替施主起了一卦。'],
        ['qingxu', '施主近来是不是夜夜发冷？汤药一天比一天苦？'],
        ['narr', '……是。'],
        ['qingxu', '施主的名字，压在阴间的生死簿上。这个月，撑不过去。'],
        ['qingxu', '中元之夜，鬼市开门。施主若去鬼王殿，把名字从簿上勾掉，或可活命。'],
        ['qingxu', '贫道言尽于此。'],
      ], after: [['narr', '清虚一走，Ngoc 就从柜台后面探出头来。'], ['ngoc', '那个人说什么，你都别信。'], ['me', '可汤药确实越来越苦。'], ['narr', 'Ngoc 的脸色变了。'], ['ngoc', '方子我一个字都没改过。药苦，不是药的事。'], ['ngoc', '……去后院看看。水缸、门槛、药柜，都看看。']], aff: { ngoc: 1 }, rw: { xp: 0.3 } },
    { id: 'm2', t: '苦药', d: '在药铺前后找找，药为什么苦（{n}/3）', hint: '药铺的后院、门槛、药柜（{n}/3）', area: 'town', goal: { clue: 'kuyao', n: 3 }, mark: 'clue:kuyao',
      after: [['ngoc', '……符灰泡的水，熬什么药都是苦的。'], ['ngoc', '喝久了，人就发冷，就做噩梦，就觉得自己快死了。'], ['me', '他想让我以为自己快死了。'], ['ngoc', '他想让你走。'], ['ngoc', '走得远远的。']], rw: { xp: 0.3 } },
    { id: 'm3', t: '红绳', d: 'Ngoc 有话问你', goal: { talk: 'ngoc' }, choice: 'go7',
      lines: [['narr', 'Ngoc 把水缸里的水全倒了，一桶一桶，倒了很久。']],
      after: [['narr', 'Ngoc 从抽屉里摸出一根红绳，一圈一圈缠在你的刀柄上，打了个死结。'], ['ngoc', '鬼市阴气重。红绳辟邪。'], ['ngoc', '……红绳要是断了，你就回来。'], ['me', '为什么？'], ['ngoc', '不为什么。'], ['ngoc', '天亮之前回来。药钱还没结呢。']], rw: { xp: 0.2 } },
    { id: 'm4', t: '同行', d: '出发前，去捕快房找珍姑娘，再去书院见龙道长（{n}/2）', goal: { talks: ['zhen', 'long'] },
      tl: {
        zhen: [['zhen', '鬼市？我跟你去。'], ['narr', '珍姑娘把一摞卷宗拍在桌上。'], ['zhen', '三年，镇上失踪了十一个人。义庄的刘师傅说，失踪的人，名字会出现在鬼市的「魂签」上。'], ['zhen', '我哥是第十二个。'], ['zhen', '人没找着。魂，总该找得着。'], ['narr', '（珍姑娘和你同行。）']],
        long: [['long', '兄台要去鬼市？在下手无缚鸡之力，只有一句话相赠——「君子不器」。'], ['long', '器，是碗，是瓢。碗只能盛饭，瓢只能舀水。君子不做碗，也不做瓢。'], ['long', '同一招，换个用法，便是另一招。'], ['narr', '（武学「变招」开放：在「修炼」页，每一招都可以选一种变招。）'], ['long', '还有——阴间的东西，最怕被人叫出真名。因为名字，是一个人在世上留下的最后一样东西。']],
      },
      set: { zhenFollow: 1, runes7: 1 }, aff: { zhen: 1, long: 1 }, rw: { xp: 0.3 } },
    // ---------- 第一幕 · 鬼市入口 ----------
    { id: 'm5', t: '通行证', d: '去义庄找刘师傅，开「阳人入市通行证」', hint: '义庄在镇子东边。', goal: { talk: 'liu' }, quiz: 'tongxing',
      lines: [['liu', '鬼市？义庄后门，中元夜通鬼市。'], ['liu', '阳人入市，原则上要开「阳人入市通行证」。'], ['liu', '这个规矩，是我三十年前在县衙当师爷的时候定的。'], ['zhen', '……鬼市的规矩，是你定的？'], ['liu', '原则上，是县太爷定的。实际上，是我写的。'], ['liu', '按规矩，问你三个问题。']],
      after: [['narr', '刘师傅从抽屉里摸出一张黄纸，「啪」地盖了个章。章盖歪了。'], ['liu', '……原则上，盖歪了也作数。'], ['liu', '记住：天亮之前，必须出来。']], aff: { liu: 1 }, rw: { xp: 0.3 } },
    { id: 'm6', t: '没影子的人', d: '康总管一头撞进了义庄', goal: { talk: 'kang' },
      lines: [
        ['kang', '好兄弟——！'],
        ['narr', '康总管一头撞进义庄，扑通一声跪在你面前。'],
        ['kang', '带我去！带我去鬼市！'],
        ['me', '你去干什么？'],
        ['narr', '他没说话，只是往旁边让了一步。'],
        ['narr', '油灯底下，你的影子、珍姑娘的影子、刘师傅的影子，都在墙上晃。'],
        ['narr', '康总管站的那块地方，什么都没有。'],
        ['kang', '十年前，我在鬼市的赌坊里，拿影子押了一桌满汉全席。'],
        ['kang', '输了。'],
        ['liu', '……没影子的人，活不过五十。'],
        ['kang', '我今年四十九。下个月，五十。'],
        ['zhen', '……你这十年，就是这么过来的？'],
        ['kang', '吃呗。能吃一顿是一顿。'],
        ['narr', '他笑了一下。笑得比哭还难看。'],
      ], set: { kangFollow: 1 }, rw: { xp: 0.2 } },
    { id: 'm7', t: '中元夜', d: '鬼市只在夜里开。天黑以后，从义庄北墙的后门进鬼市', hint: '天还亮着的话，先在义庄的火盆边歇一歇，等天黑。', area: 'yizhuang7', goal: { enter: 'guishi' }, mark: 'gsfire', tod: 'night',
      lines: [['narr', '中元夜。'], ['narr', '义庄后门「吱呀」一声开了。门外不是荒坟——是一条长街，两边挂满了白灯笼。'], ['narr', '街上人来人往。不，是鬼来鬼往。'], ['kang', '（小声）别回头。鬼市里，有人叫你名字，千万别答应。'], ['zhen', '为什么？'], ['kang', '答应了，名字就是它的了。']], rw: { xp: 0.3 } },
    // ---------- 第二幕 · 鬼市 ----------
    { id: 'm8', t: '熟面孔', d: '街边有个描灯笼的小鬼，看着眼熟', hint: '鬼市东南，堆满纸灯笼的小桌子。', goal: { talk: 'shutong' }, tod: 'night',
      lines: [
        ['shutong', '……恩、恩公？！'],
        ['narr', '街边一张小桌子，桌上堆满了纸灯笼。一个瘦瘦的小鬼抬起头，手里的毛笔「啪」地掉了。'],
        ['narr', '是书童阿福。'],
        ['shutong', '恩公也、也死了？！'],
        ['me', '没有。来办点事。'],
        ['shutong', '吓、吓死我了……我是说，我已经死了，吓不死……'],
        ['shutong', '我在鬼市给人描河灯，一盏三个铜板。'],
        ['shutong', '阳间的人中元节放河灯，灯上写着名字。漂到忘川，名字被水泡花了，就得有人重新描一遍。'],
        ['shutong', '不然……就没人认得出，这盏灯是给谁的了。'],
        ['zhen', '鬼市里，打听事情找谁？'],
        ['shutong', '鬼、鬼货郎。他什么都知道。不过他不收钱，他收……记忆。'],
        ['shutong', '还、还有——鬼市里买东西得用冥币。阳间的银子，得先去西北边的钱庄换。'],
      ], rw: { xp: 0.2 } },
    { id: 'm9', t: '鬼钱庄', d: '阳间的银子在鬼市不好使。去鬼钱庄换冥币（夜里）', hint: '鬼市西北，挂着「钱」字幡的那家。', goal: { talk: 'qianzhuang' }, tod: 'night',
      lines: [
        ['qianzhuang', '阳人？'],
        ['narr', '钱庄的柜台后面坐着一个戴瓜皮帽的鬼，手边一架算盘，算珠是一颗一颗的牙。'],
        ['qianzhuang', '原则上，阳间的银子在鬼市不算钱。'],
        ['qianzhuang', '实际上——十两换一枚冥币。'],
        ['zhen', '……你这话，跟义庄的刘师傅一个调调。'],
        ['qianzhuang', '刘师爷？那是我师父。三十年前他来鬼市备案，我给他磨了三个月的墨。'],
        ['qianzhuang', '看在师父面子上，头一回开户，送你八十枚。'],
        ['narr', '（鬼市的摊子都能买东西了：兵器铺、当铺、奇珍阁、赌坊、鬼厨子、纸扎铺，还有鬼货郎的情报。冥币不够，就在钱庄换，或者把用不上的东西拿去当铺当。）'],
      ], rw: { xp: 0.2, mb: 80 } },
    { id: 'm10', t: '鬼货郎', d: '找鬼货郎打听消息（只在夜里出摊）', hint: '鬼市西边，挑着担子的那个。', goal: { talk: 'huolang' }, tod: 'night',
      lines: [
        ['huolang', '阳人？稀客稀客～'],
        ['narr', '鬼货郎挑着一副担子，两头挂满了小瓶子。每个瓶子里，都飘着一缕白烟。'],
        ['huolang', '这些？都是记忆。有人卖了初恋，有人卖了娘做的饭的味道。'],
        ['huolang', '想打听事？鬼市的规矩：记忆换记忆。您给我一段您的，我给您一段别人的。'],
        ['narr', '你想了想，给了他一段：古树下，青木子拍着你的肩，说「钉子在，人就在」。'],
        ['narr', '那段记忆从你额头上被抽了出来，钻进一个小瓶子。你还记得这件事——只是想起来的时候，不那么暖了。'],
        ['huolang', '……好东西。三百年的陈货。'],
        ['huolang', '我给您一段：三个月前，一个白衣道士来鬼市，跟鬼王喝了一夜酒。'],
        ['huolang', '走的时候，他说：「中元那天，有个小子会来。留住他。」'],
        ['zhen', '……留住？'],
        ['huolang', '鬼王殿留人，只有一种留法。'],
        ['huolang', '对了——生死簿在鬼王殿。您的名字在不在上面，得进了殿才知道。'],
        ['huolang', '鬼王殿的门，子时才开。'],
      ], rw: { xp: 0.3 } },
    { id: 'm11', t: '赌坊', d: '康总管的影子押在赌坊里。进赌坊看看', hint: '鬼市北边那间最大的铺子。', goal: { talk: 'dufang' }, tod: 'night',
      lines: [
        ['kang', '好兄弟，我的影子……就押在这儿。'],
        ['dufang', '哟，这不是十年前那个胖子吗？又来了？这回押什么？'],
        ['kang', '我、我来赎影子！'],
        ['dufang', '赎？鬼市赌坊，只赌不赎。想要回去，就赢回去。'],
        ['dufang', '不过——没筹码，不上桌。阳间的铜钱，在这儿一文不值。'],
        ['kang', '筹码……筹码上哪儿换？'],
        ['dufang', '当铺。拿东西去当。'],
        ['dufang', '嘿嘿，阳人身上，能当的东西可不多。'],
      ], rw: { xp: 0.2 } },
    { id: 'm12', t: '当名字', d: '去鬼当铺换筹码', hint: '鬼市南边，柜台很高的那家。', goal: { talk: 'guidang' }, tod: 'night',
      lines: [
        ['guidang', '当东西？'],
        ['narr', '当铺的柜台很高，你只看得见一双眼睛。'],
        ['guidang', '阳人的东西，我这儿只收一样：名字。'],
        ['guidang', '当一个名字，换十枚筹码。赎回来，二十枚。'],
        ['zhen', '名字也能当？'],
        ['guidang', '当了名字，别人就叫不出你来了。你自己……也慢慢就忘了。'],
        ['me', '我来——'],
        ['kang', '我当！'],
        ['narr', '康总管一把把你推开，扒在柜台上。'],
        ['kang', '我的名字不值钱！当了！'],
        ['me', '康总管——'],
        ['kang', '好兄弟，那是我的影子。得我自己来。'],
        ['guidang', '……成交。'],
        ['narr', '当铺里一道白光闪过。康总管晃了一下。'],
        ['narr', '你张嘴想叫他——忽然叫不出来了。'],
        ['narr', '他是谁来着？醉仙楼的……那个胖子。'],
        ['kangx', '……我刚才说什么来着？'],
        ['kangx', '哦对。筹码。走，赌钱去！'],
      ], set: { kangNoName: 1 }, rw: { xp: 0.2 } },
    { id: 'm13', t: '押影子', d: '回赌坊，把胖子的影子赢回来', hint: '赌坊。押大小，三局两胜。', goal: { talk: 'dufang' }, mini: 'dice', tod: 'night',
      lines: [['dufang', '十枚筹码。押影子？行。'], ['dufang', '你赢，影子归你。你输——'], ['dufang', '你的影子也归我。'], ['kangx', '押！押我的！'], ['dufang', '你？你连名字都没了，还押什么？让那个阳人来。']],
      after: [['narr', '一团黑乎乎的影子从骰盅底下爬了出来，缩在桌脚，抖了一下。'], ['narr', '它慢慢爬到胖子脚下，贴了上去。'], ['kangx', '……它瘦了。'], ['kangx', '这十年，它也没吃饱吧。'], ['dufang', '筹码也拿走。三十枚。鬼市的规矩，赢家不能空手出门。']],
      aff: { kang: 2 }, rw: { xp: 0.4, gold: 300 } },
    { id: 'm14', t: '赎名字', d: '拿筹码去当铺，把胖子的名字赎回来', goal: { talk: 'guidang' }, tod: 'night',
      lines: [
        ['guidang', '赎名字？二十枚。'],
        ['narr', '你把筹码推过去。当铺里又是一道白光。'],
        ['narr', '胖子打了个喷嚏。'],
        ['kang', '……康。'],
        ['kang', '我姓康！康、康……'],
        ['kang', '康福贵！我叫康福贵！'],
        ['narr', '他一把抱住你，哭得鼻涕都出来了。'],
        ['kang', '我爹给我起这个名字，是盼我又有福又有贵。'],
        ['kang', '福，有了。贵，也算有了。'],
        ['kang', '就是这十年，没人叫过我的名字。都叫我「康总管」。'],
        ['zhen', '……康福贵。'],
        ['kang', '哎！'],
        ['zhen', '鼻涕擦擦。'],
      ], after: [['narr', '街那头传来一声鸡叫。天快亮了。'], ['zhen', '魂签挂在西墙。夜里鬼挤鬼，看不清。'], ['zhen', '等天亮收了摊，我一根一根看。']],
      set: { kangNoName: 0 }, aff: { kang: 1, zhen: 1 }, rw: { xp: 0.3 } },
    { id: 'm15', t: '魂签', d: '天亮以后，去西墙看魂签（{n}/3）', hint: '在鬼市的灯笼下歇一歇，天就亮了。西墙上挂满了木签（{n}/3）', area: 'guishi', goal: { clue: 'hunqian', n: 3 }, mark: 'clue:hunqian', tod: 'day',
      after: [['narr', '签子背面，刻着一行小字：「担保：黄泉路·马面」。'], ['zhen', '借魂，还要找担保。'], ['zhen', '……马面。'], ['zhen', '走。去黄泉路。']], aff: { zhen: 1 }, rw: { xp: 0.4 } },
    { id: 'm16', t: '奈何桥', d: '黄泉路尽头，有一座桥', hint: '黄泉路一直往东。', area: 'huangquan', goal: { reach: 'naihe' }, mark: 'naihe',
      lines: [
        ['narr', '黄泉路的尽头，是一条黑色的河。'],
        ['narr', '河上一座灰石桥。桥下漂着一盏一盏的河灯，每一盏上都写着一个名字。'],
        ['narr', '有的名字新，有的名字花了。阿福说得没错——花了的灯，就没人认得了。'],
        ['narr', '你蹲在桥头，一盏一盏地看。'],
        ['narr', '你在找「阿土」。'],
        ['narr', '没有。'],
        ['zhen', '……没有是好事。'],
        ['zhen', '灯是活人放给死人的。没有你的灯，说明你还没死透。'],
        ['me', '……也说明，三百年来，没有一个人记得我。'],
        ['narr', '珍姑娘没说话。过了一会儿，她从怀里掏出一张纸，折了一盏小小的河灯，在上面写了两个字，放进河里。'],
        ['narr', '「阿土」。'],
        ['zhen', '现在有了。'],
        ['zhen', '……走。马面在对岸。'],
      ], aff: { zhen: 2 }, rw: { xp: 0.3 } },
    { id: 'm17', t: '马面', d: '过奈何桥，找到给魂签作担保的马面', hint: '忘川对岸，东北边。', area: 'huangquan', goal: { kill: 'mamian', n: 1 }, mark: 'mon:mamian',
      lines: [
        ['mamian', '别打了！别打了！我说！我说！'],
        ['mamian', '那道士每个月来一回，从奈何桥上带走一个魂。签子上写「借」，其实……就没打算还。'],
        ['zhen', '他要那么多魂干什么？'],
        ['mamian', '炼、炼东西！我不知道！我就是个担保的！他给我烧了三年纸钱！'],
        ['mamian', '他上回来，说这是最后一回了。'],
        ['mamian', '他说，下一个……不用借了。'],
        ['mamian', '会自己送上门。'],
        ['narr', '你后背一凉。可你想不出来，他说的是谁。'],
      ], after: [['zhen', '……子时快到了。'], ['zhen', '回鬼市。鬼王殿的门，该开了。']], rw: { xp: 0.5 } },
    { id: 'm18', t: '名帖', d: '鬼王殿只认名帖。去纸扎铺订一张（夜里）', hint: '鬼市东南，门口站着纸人的那家。', goal: { get: 'mingtie' }, mark: 'zhizha', tod: 'night',
      lines: [['narr', '名帖揣进怀里，薄薄一张，却沉得很。']], rw: { xp: 0.2 } },
    { id: 'm19', t: '子时开殿', d: '回鬼市，鬼王殿门口有个看门的鬼差（夜里）', hint: '鬼市正北的大门。', goal: { talk: 'guicha' }, tod: 'night',
      lines: S => [
        ['guicha', '站住！'],
        ['guicha', '鬼王殿，原则上，阳人免进。'],
        ['zhen', '……原则上？'],
        ['guicha', '这是规矩。三十年前，一个阳间的师爷定的。我在这儿看了三十年门，就学会了这一句。'],
        ['guicha', '原则上，免进。实际上——'],
        ['narr', '他翻开名册，手指在上面划了一下，停住了。'],
        ['guicha', '……上头吩咐过：中元夜，有个阳人要来。放他进去。'],
        ...(S.flags.callBai7 ? [['guicha', '上头还说：那小子已经认出他来了。见了面，别客气。']] : S.flags.playAlong7 ? [['guicha', '上头还说：那小子什么都不知道，好打发。']] : []),
        ['guicha', '请。'],
        ['narr', '殿门「轰隆隆」地开了。'],
        ['zhen', '……太顺了。'],
        ['kang', '顺、顺还不好吗？'],
        ['zhen', '还没敲门，门自己开了。是好事吗？'],
      ], set: { gateOpen7: 1 }, rw: { xp: 0.2 } },
    // ---------- 第三幕 · 鬼王殿 ----------
    { id: 'm20', t: '鬼王殿前', d: '进鬼王殿的大门', goal: { enter: 'guiwang' }, mark: 'gwfire',
      lines: [['narr', '大门在身后「砰」地关上了。'], ['narr', '院子里静悄悄的。一排一排的石柱，柱子后面黑漆漆的。'], ['kang', '我、我就在门口等你们……'], ['narr', '康福贵缩在门边，抱着一根柱子不撒手。']], rw: { xp: 0.2 } },
    { id: 'm21', t: '留住他', d: '穿过院子', hint: '院子正中。', area: 'guiwang', goal: { reach: 'gwamb' }, mark: 'gwamb',
      waves: [{ kind: 'battle', mon: 1, n: 3, lv: 26 }, { kind: 'battle', mon: 5, n: 3, lv: 26, mix: [1, 5, 4] }, { kind: 'elite', mon: 1, lv: 27, name: '鬼差头领' }],
      lines: [['narr', '你走到院子正中。'], ['narr', '四面八方的石柱后面，同时亮起了一双一双鬼火似的眼睛。'], ['guicha', '鬼王有令——留住阳人！'], ['zhen', '果然。']],
      between: [[['kang', '（门口）还有！左边还有！']], [['zhen', '后面那个大的——小心！']]],
      after: [['narr', '最后一个鬼差散成了黑烟。'], ['narr', '殿门前的五盏魂灯，「噗」地一起亮了一下，又灭了。']], rw: { xp: 0.6 } },
    { id: 'm22', t: '报上名来', d: '殿门前有五盏魂灯，每盏灯上一个字', hint: '殿门上写着「报上名来」。点灯的顺序，就是你的名字。', area: 'guiwang', goal: { puzzle: 'mingdeng' }, mark: 'lamp:mingdeng',
      lines: [['narr', '殿门「吱呀」一声，开了一道缝。'], ['narr', '门缝里飘出一个声音，懒洋洋的：'], ['guiwang', '……阿土？'], ['guiwang', '进来吧。等你半天了。']], rw: { xp: 0.4 } },
    { id: 'm23', t: '鬼王', d: '进鬼王殿', goal: { fight: 'boss7' }, mark: 'boss7',
      lines: [['narr', '鬼王殿正中，一张黑石王座。王座上歪坐着一个高大的影子。'], ['guiwang', '阳人。'], ['guiwang', '有个道士托我，把你留在这儿。'], ['guiwang', '他答应我，事成之后，在阳间给我修一座庙。'], ['guiwang', '有庙，就有香火。有香火，就有人念我的名字。'], ['guiwang', '……你就安心留下吧。']],
      after: [['narr', '鬼王从王座上滚了下来，身上的黑气一缕一缕往外散。'], ['guiwang', '……那个道士……答应过……给我一座庙……']],
      set: { bossDead: 1 }, rw: { xp: 0.8, item: 'rare' } },
    { id: 'm24', t: '王小六', d: '鬼王还没散', goal: { talk: 'guiwang' }, choice: 'pai7',
      lines: [
        ['guiwang', '……你还不走？'],
        ['me', '你叫什么名字？'],
        ['narr', '鬼王愣住了。'],
        ['guiwang', '……三百年了。没人问过。'],
        ['guiwang', '我是守城的兵。城破那天，死了三千个。坟里埋了三千个，碑上一个名字都没刻。'],
        ['guiwang', '我在这儿当了三百年鬼王，就想要一座庙。'],
        ['guiwang', '有一座庙，就有人念我的名字。'],
        ['guiwang', '……王小六。我叫王小六。'],
      ], after: [['narr', '王座底下，有什么东西在发光。']], rw: { xp: 0.3 } },
    { id: 'm25', t: '生死簿', d: '王座底下压着一页纸', area: 'guidian', goal: { clue: 'canye', n: 1 }, mark: 'clue:canye',
      after: [
        ['narr', '你的名字底下，没有勾，没有叉。'],
        ['narr', '清虚说你撑不过这个月——生死簿上，根本没有这回事。'],
        ['narr', '然后，一样一样的东西，从纸上涌进你脑子里。'],
        ['narr', '山脚的小屋。百家饭。张婶的窝头，李叔的咸菜。'],
        ['narr', '山坡上的五个人。饭篮。'],
        ['narr', '还有——白狐的眼睛。'],
        ['narr', '「我等你。」'],
        ['narr', '你刀柄上那根红绳，「啪」地断了。'],
        ['zhen', '……怎么了？'],
        ['me', '药铺。'],
        ['narr', '你转身就跑。'],
        ['zhen', '你去药铺！我去白云观盯着！'],
      ], set: { zhenFollow: 0, noComp: 1 }, tele: ['town', 'f', 'towncamp'], rw: { xp: 0.4, gold: 500, key: 'canye7' } },
    // ---------- 第四幕 · 药铺空了 ----------
    { id: 'm26', t: '药铺空了', d: '药铺', area: 'town', goal: { clue: 'yaopu', n: 1 }, mark: 'clue:yaopu',
      after: [['narr', '你站在空荡荡的药铺里，站了很久。'], ['narr', '然后你把铃铛系在刀柄上，系在那根断了的红绳原来的地方。'], ['narr', '铃铛没有响。']], rw: { xp: 0.3, key: 'hulingdang' } },
    { id: 'm27', t: '小虎', d: '小虎在街上找你', goal: { talk: 'xiaohu' },
      lines: [
        ['xiaohu', '哥哥！'],
        ['narr', '小虎从街角跑过来，眼睛哭得通红。'],
        ['xiaohu', 'Ngoc 姐姐昨晚一直站在药铺门口等你。等到半夜。'],
        ['xiaohu', '后来白云观的小道童来了，跟她说了几句话。'],
        ['xiaohu', '她就把门口的灯笼吹了，跟着走了。'],
        ['xiaohu', '我追上去问她去哪儿。她摸了摸我的头，说：「去还一笔账。」'],
        ['xiaohu', '……还说，让你别追。'],
        ['narr', '你攥紧了刀柄。铃铛硌着你的手心。'],
      ], rw: { xp: 0.2 } },
    { id: 'm28', t: '白云观的门', d: '珍姑娘从白云观回来了，在捕快房', goal: { talk: 'zhen' }, final: true,
      lines: [
        ['zhen', '白云观的门开了。'],
        ['narr', '珍姑娘跑得满头是汗，刀都没收。'],
        ['zhen', '我在山下看了一个时辰。上山的路上，全是人。'],
        ['zhen', '张屠户、李寡妇、卖豆腐的老王……一个个两眼发直，排着队往上走。'],
        ['zhen', '白天去上香的，晚上一个都没下来。'],
        ['zhen', '……她在那儿。对吧？'],
        ['me', '对。'],
        ['zhen', '那就走。'],
        ['zhen', '这回谁拦我，我砍谁。'],
      ], aff: { zhen: 1 }, rw: { xp: 0.3 } },
  ],
  side: [
    { id: 'S1', t: '鬼市通宝', giver: 'huolang', when: S => mPast(S, 'm10'),
      offer: [['huolang', '想要鬼市通宝？那可是硬通货，鬼王见了都得给三分面子。'], ['huolang', '三笔交易。第一笔：三朵彼岸花。第二笔：鬼市三霸，随便哪个的人头。'], ['huolang', '第三笔嘛……到时候再说。']],
      steps: [
        { d: '采彼岸花（{n}/3）', hint: '彼岸花开在黄泉路、鬼王殿前（{n}/3）', area: 'huangquan', goal: { herb: 'bian', n: 3 }, mark: 'herb:bian' },
        { d: '打倒鬼市三霸里的牛头或吊死鬼', hint: '黄泉路上。牛头在南边，吊死鬼在忘川对岸。', area: 'huangquan', goal: { kill: 'sanba', n: 1 }, mark: 'mon:sanba' },
        { d: '回鬼市找鬼货郎，做最后一笔交易（夜里）', goal: { talk: 'huolang' }, choice: 'memory7', lines: [['huolang', '花收了，人头也收了。'], ['narr', '鬼货郎把担子放下，凑近了你。']] }],
      rw: { xp: 0.5, key: 'tongbao' } },
    { id: 'S2', t: '真名', giver: 'guidang', when: S => mPast(S, 'm14'),
      offer: [['guidang', '阳人，你的名字，不止一页。'], ['guidang', '鬼王撕过生死簿。撕下来的那一页，当在我这儿。'], ['guidang', '判官笔勾名字，得先找到名字。名字不在簿上，它就勾不着你。'], ['guidang', '想赎？三枚筹码——不是你赢的那种，是鬼差押在赌坊的那种，上面刻着鬼差的名字。']],
      steps: [
        { d: '从牛头马面鬼差身上找鬼差的筹码（{n}/3）', hint: '黄泉路、鬼王殿前的牛头马面（{n}/3）', area: 'huangquan', goal: { drop: 'chouma', n: 3, mon: [1, 5], p: 0.5, dn: '鬼差的筹码' }, mark: 'monm:1' },
        { d: '去鬼当铺赎残页（夜里）', goal: { talk: 'guidang' },
          lines: [['guidang', '三枚，不多不少。'], ['narr', '残页上只有一行字，墨迹新得像是昨天才写的。'], ['narr', '「阿土。」'], ['narr', '后面本来还有字，被人用指甲刮掉了。刮得很用力。'], ['guidang', '刮名字的人，指甲缝里有朱砂。'], ['guidang', '……你知道是谁。']] }],
      rw: { xp: 0.5, key: 'zhenming' } },
    { id: 'S3', t: '正气灯', giver: 'long', when: S => mPast(S, 'm4'),
      offer: [['long', '鬼火怕正气。在下写四个字，做成一盏灯，或许有用。'], ['long', '灯要灯骨，铁蛋的手艺最好。灯要灯油——陈年香油，醉仙楼的地窖里有。']],
      steps: [
        { d: '请铁蛋做灯骨', goal: { talk: 'tiedan' }, lines: [['tiedan', '灯骨？小意思！'], ['narr', '铁蛋拿铁丝拧了一个八角灯骨，每个角上都刻了一个「铁」字。'], ['tiedan', '刻了字，鬼就知道这是我做的！'], ['me', '……鬼知道了又怎样？'], ['tiedan', '就知道我厉害呀！']] },
        { d: '找康总管要陈年香油', goal: { talk: 'kang' }, lines: [['kang', '陈年香油？'], ['narr', '他从怀里掏出一个小瓷瓶。'], ['kang', '我出门从来都带着——鬼市的东西没味儿，蘸着吃。'], ['kang', '……拿去！影子都是你帮我赢回来的！']] },
        { d: '把灯骨和香油交给龙道长', goal: { talk: 'long' }, lines: [['narr', '龙道长研了一刻钟的墨，提笔在灯纸上写了四个字：'], ['narr', '「天地正气」。'], ['narr', '灯一点，书院里的阴气，「呼」地散了。'], ['long', '在下写了一辈子字。头一回，字派上了用场。']] }],
      aff: { long: 1, kang: 1 }, rw: { xp: 0.5, key: 'zhengqideng' } },
    { id: 'S4', t: '康福贵的影子', giver: 'kang', when: S => mPast(S, 'm14'),
      offer: [['kang', '好兄弟，影子回来了，可它……不太认我。'], ['narr', '康福贵往左走，影子往右歪。他抬手，影子慢半拍。'], ['kang', '阿福说，影子离家太久，会忘了主人叫什么。得有人把名字，重新写在它背上。']],
      steps: [
        { d: '在鬼市找阿福（夜里）', goal: { talk: 'shutong' }, lines: [['shutong', '补、补影子？'], ['shutong', '写名字要用阴墨。阳间的墨，写在影子上会化。'], ['shutong', '黄泉路上的吊死鬼，袖子里藏着阴墨……'], ['kang', '……我不想知道她们拿阴墨干什么。']] },
        { d: '从吊死鬼身上找阴墨（{n}/2）', hint: '黄泉路上的吊死鬼（{n}/2）', area: 'huangquan', goal: { drop: 'yinmo', n: 2, mon: [3], p: 0.5, dn: '阴墨' }, mark: 'monm:3' },
        { d: '把阴墨交给阿福（夜里）', goal: { talk: 'shutong' }, lines: [['narr', '阿福蹲在地上，在康福贵的影子背上，一笔一划地写：「康福贵」。'], ['narr', '写完最后一笔，影子抖了一下，「嗖」地贴回了康福贵脚下。'], ['narr', '康福贵原地转了三圈。影子也转了三圈，一步都不差。'], ['shutong', '恩、恩公的朋友，名字真好听。'], ['kang', '是吧！我爹起的！']] }],
      aff: { kang: 1 }, rw: { xp: 0.4, gold: 260 } },
    { id: 'S5', t: '刘师傅的备案', giver: 'liu', when: S => mPast(S, 'm7'),
      offer: [['liu', '鬼市里，有个王老头。'], ['liu', '三十年前，县太爷让我去鬼市「备案」——把鬼市里的鬼一个一个登记造册，好让鬼差来收。'], ['liu', '名册上，原则上，每个鬼都要写。'], ['liu', '实际上……我漏写了一个。'], ['liu', '名册后来不见了。我猜，在他那儿。']],
      steps: [
        { d: '在鬼市找王老头（夜里）', goal: { talk: 'wang' }, lines: [['wang', '刘师爷的名册？……在我这儿。'], ['wang', '给你可以。先给我来一锅烟——阳间的烟。鬼市的烟，抽着没味儿。']] },
        { d: '回镇上，找雷老虎讨烟叶', goal: { talk: 'lei' }, lines: [['lei', '烟叶？给鬼抽？'], ['lei', '哈！老子这辈子就没听过这么有意思的事！'], ['narr', '雷老虎从怀里掏出一个油纸包，想了想，把自己的烟袋锅子也塞了过来。'], ['lei', '整套的！让他抽个痛快！']] },
        { d: '把烟叶带给王老头（夜里）', goal: { talk: 'wang' }, lines: [
          ['narr', '王老头点上烟，吸了一大口，眯着眼睛半天没说话。'], ['wang', '……是这个味儿。'],
          ['wang', '三十年前，刘师爷提着名册来鬼市。鬼差跟在他屁股后面，名册上写一个，就收一个。'],
          ['wang', '写到我这儿，他的笔停了。他问我：「老人家，你在阳间还有人吗？」'],
          ['wang', '我说有个孙子，七岁，没人管。'],
          ['wang', '他就把笔放下了。'],
          ['wang', '……我多活了这三十年。偷偷回去看了孙子十二回。'],
          ['narr', '他把一本发霉的名册递给你。名册最后一页，有一行被墨涂掉的名字。']] },
        { d: '把名册交给刘师傅', goal: { talk: 'liu' }, lines: [['liu', '……他还记得。'], ['narr', '刘师傅翻到最后一页，看着那团墨，看了很久。'], ['liu', '原则上，我那是违规操作。'], ['liu', '实际上——'], ['liu', '……我不后悔。'], ['narr', '他把名册锁进抽屉最底下一格。钥匙，他扔进了火盆。']] }],
      aff: { liu: 2 }, rw: { xp: 0.5, item: 'rare' } },
    { id: 'S6', t: '通缉：鬼市三霸', giver: 'lei', when: S => mPast(S, 'm17'),
      offer: [['lei', '鬼市三霸？马面让你收拾了？'], ['lei', '哈！剩下牛头和吊死鬼，一个不留！赏银五百，老子出！']],
      steps: [
        { d: '在黄泉路打倒牛头和吊死鬼（{n}/2）', hint: '黄泉路南边、忘川对岸东南（{n}/2）', area: 'huangquan', goal: { kill: 'sanba', n: 2 }, mark: 'mon:sanba' },
        { d: '回镖局领赏', goal: { talk: 'lei' }, lines: [['lei', '鬼也敢打！老子服你！'], ['lei', '回头给你在镖局门口挂块匾！就写——「打鬼的」！']] }],
      rw: { gold: 500, xp: 0.4, item: 'rare' } },
    { id: 'S7', t: '河灯', giver: 'shutong', when: S => mPast(S, 'm8'),
      offer: [['shutong', '恩公……'], ['shutong', '今年中元，我娘……给我放河灯了吗？'], ['shutong', '我在忘川边上描了三年灯，一盏一盏地找。没有找着写「阿福」的。'], ['shutong', '是不是……她不记得我了？']],
      steps: [
        { d: '回镇上问问阿福娘', goal: { talk: 'mother' }, lines: [['mother', '阿福的河灯？'], ['narr', '阿福娘从屋里捧出一盏河灯。灯纸是新糊的，上面工工整整写着两个字：「阿福」。'], ['mother', '我年年都放。'], ['mother', '可河灯漂不远。到了镇口那道坝，就卡住了，灯就灭了。'], ['mother', '……你要是能见着他，帮我把灯带过去。'], ['mother', '灯里我塞了一块糖糕。他打小就爱吃。']] },
        { d: '把河灯带给阿福（夜里）', goal: { talk: 'shutong' }, lines: [['narr', '你把河灯递给阿福。'], ['narr', '阿福捧着灯，看着上面的两个字，半天没动。'], ['shutong', '是、是我娘的字。'], ['shutong', '她写「福」字，右边的「田」总写得大一点……'], ['narr', '他把灯里的糖糕掰了一小块，放进嘴里。鬼是吃不出味道的。'], ['shutong', '……甜的。'], ['shutong', '恩公，我不用再找了。'], ['shutong', '她记得。']] }],
      rw: { xp: 0.4, item: 'rare' } },
    { id: 'S8', t: '光脚的小鬼', giver: 'xiaogui', when: S => mPast(S, 'm7'),
      offer: [['xiaogui', '大哥哥，你知道我叫什么吗？'], ['narr', '一个小鬼蹲在路边，五六岁的样子，光着脚。'], ['xiaogui', '我忘了。桥上的婆婆说，记不起名字的，不能过桥。'], ['xiaogui', '我在这儿等了好久好久了。'], ['xiaogui', '我记得……我有个拨浪鼓，一双鞋，还有一个娘给我缝的东西。都丢在路上了。']],
      steps: [
        { d: '在黄泉路上找小鬼丢的东西（{n}/3）', hint: '黄泉路西南、北边，还有忘川对岸（{n}/3）', area: 'huangquan', goal: { clue: 'xgui', n: 3 }, mark: 'clue:xgui' },
        { d: '把东西交给小鬼', goal: { talk: 'xiaogui' }, lines: [['narr', '你蹲下来，把拨浪鼓、虎头鞋、围兜，一样一样放在他面前。'], ['narr', '小鬼摸了摸围兜上的字。'], ['me', '豆豆。'], ['xiaogui', '……豆豆。'], ['xiaogui', '豆豆！我叫豆豆！娘叫我豆豆！'], ['narr', '他抱着拨浪鼓，一路摇着，跑上了奈何桥。'], ['narr', '跑到桥中间，他回过头，冲你挥了挥手。'], ['narr', '然后，就不见了。']] }],
      rw: { xp: 0.4, gold: 200 } },
    { id: 'S9', t: '王小六的牌位', giver: 'liu', when: S => !!S.flags.pai7 && mPast(S, 'm24'),
      offer: [['liu', '听说……你答应鬼王，在义庄给他立个牌位？'], ['liu', '原则上，义庄不给鬼立牌位。']],
      steps: [{ d: '跟刘师傅说说王小六', goal: { talk: 'liu' }, lines: [['liu', '实际上……'], ['narr', '刘师傅从柜子里翻出一块木牌，吹了吹灰，提笔写了三个字：「王小六」。'], ['narr', '字写得端端正正。'], ['liu', '三十年前，我漏写了一个名字，救了一个鬼。'], ['liu', '今天我多写一个名字。也算……还上了。'], ['narr', '他把牌位摆在义庄最高的那层架子上，点了一炷香。']] }],
      aff: { liu: 1 }, rw: { xp: 0.3, item: 'rare' } },
    { id: 'S10', t: '珍大的菜刀', giver: 'guidang', when: S => mPast(S, 'm15'),
      offer: [['guidang', '跟着你的那个女捕快……姓珍？'], ['guidang', '三年前，有个厨子来当过一把菜刀。他说他要出趟远门，刀先押在这儿。'], ['guidang', '他说，要是他妹妹哪天来了，就把刀给她。'], ['guidang', '……他再也没来赎。现在是死当了。'], ['zhen', '……多少钱？'], ['guidang', '六十枚冥币。原则上，死当不打折。']],
      steps: [{ d: '在当铺把那把菜刀赎回来（夜里，六十枚冥币）', hint: '鬼当铺的「赎死当」里。', goal: { get: 'caidao' }, mark: 'guidang',
        lines: [['narr', '一把旧菜刀。刀柄上缠着红绳，刻着一个歪歪扭扭的「珍」字。'], ['zhen', '……'], ['zhen', '这是我十岁那年，他教我切葱用的刀。'], ['zhen', '「珍」字是我刻的。刻歪了，他说正好，歪的才认得出来。'], ['narr', '珍姑娘把菜刀插在腰后，和她的捕快刀并排。'], ['zhen', '他欠我一顿饭。等他回来，让他用这把刀做。']] }],
      aff: { zhen: 2 }, rw: { xp: 0.4, item: 'rare' } },
    { id: 'S11', t: '偷钱袋的小鬼', giver: 'xiaotou', when: S => mPast(S, 'm9'),
      offer: [['xiaotou', '别、别打我！钱还你！还多给你十枚！'], ['narr', '小鬼把钱袋塞回你手里，缩成一团。'], ['me', '偷钱干什么？'], ['xiaotou', '……买河灯。'], ['xiaotou', '中元节，要给娘放一盏河灯。灯上要写娘的名字。'], ['xiaotou', '可我死的时候太小了，不会写字。娘的名字……我也想不起来了。'], ['xiaotou', '我只记得，娘叫我的时候，总说「狗蛋，回家吃饭」。']],
      steps: [
        { d: '去纸扎铺买一盏空白的河灯（夜里）', goal: { get: 'hedeng7' }, mark: 'zhizha' },
        { d: '把河灯交给偷钱袋的小鬼', goal: { talk: 'xiaotou' }, lines: [['narr', '你把河灯递给他。他捧着灯，半天不知道写什么。'], ['me', '不知道娘的名字，就写你自己的。'], ['me', '她认得出来。'], ['narr', '你握着他的手，在灯上写了两个字：「狗蛋」。'], ['narr', '小鬼盯着那两个字，忽然咧开嘴笑了。'], ['xiaotou', '回家吃饭！'], ['narr', '他抱着灯，一溜烟跑向了黄泉路。']] }],
      rw: { xp: 0.4, gold: 200 } },
    { id: 'S12', t: '鬼市三鲜', giver: 'guichu', when: S => mPast(S, 'm9'),
      offer: [['guichu', '阳人，敢不敢把我三样招牌都尝一遍？'], ['guichu', '还魂饼、阴果冻、冥糖葫芦。尝完了，我把方子告诉你。'], ['kang', '方子？！我来记！我来记！']],
      steps: [
        { d: '在鬼厨子的摊子上吃三样小吃（{n}/3）', hint: '鬼厨子的摊子，夜里出摊（{n}/3）', goal: { eat: 'gs', n: 3 }, mark: 'guichu' },
        { d: '跟鬼厨子讨方子', goal: { talk: 'guichu' }, lines: [['guichu', '吃得下？好！阳人里头，你是头一个。'], ['guichu', '方子就一句：阴间的东西，要拿阳间的火来做。'], ['kang', '……就这？'], ['guichu', '就这。你回去试试。'], ['narr', '（美食图谱：「鬼市三鲜」。在醉仙楼找康总管就能吃到。）']] }],
      aff: { kang: 1 }, rw: { xp: 0.3, flag: 'dish7', mb: 30 } },
  ],
};

// ==================== 第八章 · 白云观（主题：怕死）  + 幕间四 · 出征前夜 ====================
// 主线：珍姑娘的地图 → 刘师傅的道籍 → 龙道长三十年前摔的那支笔 → 康福贵的送菜车 → 铁蛋的钥匙 → 山脚茶棚
//       → 第一道岗 → 前殿里的熟面孔 → 摸进偏殿 → 「献天狐一只」→ 人丹 → 珍大 → 压丹火 → 经阁 → 白云子的日记 → 日记交给谁
//       → 后院 → 镜阵·木之钉 → 假金子·金之钉 → 丹火·火之钉 → 钉子齐了 → 天坑边的 Ngoc → 清虚 / 白云子 → 珍大回魂 → 白狐毛
// 幕间四：坑口的大旗 → 小虎 → 私房钱 → 路引 → 这盘留着 → 令牌 → 一桌菜 → 重铸土之钉 → 空药铺 → 天亮
Object.assign(SPEAKERS, {
  zhenda:   { n: '珍大', spr: 'blade', pal: { H: '#2a1a1a', B: '#4a3a2a' } },
  daoshi:   { n: '巡逻道士', spr: 'taoist', pal: { B: '#e8e4d8' } },
  xiaosong: { n: '道童小松', spr: 'taoist', pal: { B: '#d8d0c0', H: '#2a1a1a' } },
  baiyun2:  { n: '白云子', spr: 'taoist', pal: { B: '#2a0a14', W: '#d0d0d0', H: '#808080', S: '#8a8a7a', Y: '#c4291f' } },
  wangsao:  { n: '王二嫂', spr: 'villager', pal: { H: '#2a1a1a', B: '#8a5a6a' } },
  zhaigong: { n: '胖斋公', spr: 'merchant', pal: { B: '#d8c8a0', S: '#e8d0b0' } },
  laosun:   { n: '豆腐坊的老孙头', spr: 'oldman', pal: { B: '#6a6a5a' } },
});
Object.assign(W_KEYS, {
  xinghun:  { n: '醒魂香', d: '被白云子控制的信徒，闻了就醒。他躲在信徒后面也没用了。', spr: 'fu' },
  xianghuo: { n: '对过的香火账', d: '三百年的香火，一笔一笔记着名字。他偷来的寿，念出名字就回不到他身上。', spr: 'scroll' },
  kongfu:   { n: '小松换的空白符', d: '雷坛上的天雷符，全被小松换成了白纸。', spr: 'fu' },
  sanding:  { n: '夺回的钉子', d: '木、金、火三枚钉子都在你手里。白云子的四钉阵，一个阵眼都摆不起来。', spr: 'key' },
  luyin:    { n: '阳人入阴路引', d: '刘师傅开的。原则上，这个章在阴间不一定好使。', spr: 'scroll' },
  lingpai:  { n: '珍姑娘的捕快令牌', d: '「回来还我。」', spr: 'i_amulet' },
  canye7:   { n: '生死簿残页', d: '鬼王座下那页生死簿。上面写着「阿土」，阳寿未尽。', spr: 'scroll' },
  baihumao: { n: '白狐毛', d: '一根雪白的狐狸毛。风把它吹回了药铺门口。', spr: 'herb' },
});
WNPC.zhenda = { idle: ['妹，饭做好了吗？', '……我做了个很长的梦。梦里一直在切葱。'] };
WNPC.daoshi = { idle: ['……'] };
WNPC.xiaosong = { idle: ['我、我只是来送水的……', '她走的时候，问我白云观的饭好不好吃。'] };
WNPC.wangsao = { idle: ['我家那口子又不见了！上回是乱葬岗，这回是道观！', '他这人，就是管不住嘴。'] };
WNPC.zhaigong = { idle: ['阿弥……不对，无量天尊。', '斋堂的素菜，全观最好吃。'], shop: 'zhaitang' };
WNPC.laoban.at = (WNPC.laoban.at || []).concat([{ when: S => S.ch === 8, t: '又见面了，小兄弟。茶还是那个茶，人都上山了。' }]);
WNPC.laoban.shop = 'chapeng'; WNPC.laoban.shopWhen = S => S.ch === 8 && mPast(S, 'm6');

