DOSSIER.boss8 = { n: '清虚道长 → 白云子', d: '五位镇妖师里最年轻、最怕死的那一个。三百年前，他躲在山坡后面的草丛里。', items: [
  { n: '信徒肉盾', d: '叫被控制的信徒挡在前面，他受到的伤害少三成多', key: 'xinghun', how: '醒魂香——龙道长的方子、康福贵的香料、珍姑娘的药引（支线「醒魂香」）' },
  { n: '偷天换日', d: '从信徒的香火里抽寿，给自己回血', key: 'xianghuo', how: '对过的香火账——前殿、偏殿、经阁里各有一本香火簿，交给珍姑娘对账（支线「香火账」）' },
  { n: '天雷符', d: '蓄力后引天雷，劈所有人', key: 'kongfu', how: '小松换的空白符——前殿西厢的道童小松（支线「道童小松」）' },
  { n: '四钉阵', d: '拿偷来的钉子列阵', how: '主线里把木、金、火三枚钉子都夺回来，他就摆不起阵' },
  { n: '蜕皮现形', d: '半血后撕下道袍，变得更快更狠', skill: 'armor', how: '用能「破甲」的技能打，他那张皮就挂不住' }] };

// 刘师傅的官腔·第四弹
QUIZ.daoji = [
  { q: [['liu', '「道籍转入证明」，原则上要写清三件事。'], ['liu', '第一：转入人的道号。你叫什么？']],
    opts: [['阿土', false, [['liu', '真名？你想让他们一眼就认出你？']]], ['清风', true, [['liu', '清风。好，普普通通，谁也不会多看一眼。']]], ['土道长', false, [['liu', '……你在开玩笑。']]]] },
  { q: [['liu', '第二：转出的道观。']],
    opts: [['青城山', false, [['liu', '太有名了，一查就露馅。']]], ['乱葬岗义庄', true, [['liu', '义庄也算道观？'], ['liu', '原则上不算。可他们不会去查。']]], ['白云观', false, [['liu', '从白云观转进白云观？']]]] },
  { q: [['liu', '第三：转入理由。']],
    opts: [['仰慕清虚道长', true, [['liu', '「仰慕」——这两个字，官场上最好使。'], ['narr', '刘师傅盖了章。章盖得端端正正。'], ['liu', '原则上，道观也归县衙管。'], ['liu', '实际上……也不归。'], ['liu', '所以这张纸，原则上是假的。实际上，比真的还真。']]], ['来砍人', false, [['liu', '……写「仰慕」。']]]] }];
// 第一道岗：小道童验货。说错一句，他就去报信
QUIZ.yanhuo = [
  { q: [['daotong', '站住！送菜的？'], ['daotong', '车上装的什么？']],
    opts: [['醉仙楼的素菜', true, [['daotong', '嗯。']]], ['人', false, [['daotong', '……啊？'], ['kang', '人、人参！他说人参！'], ['daotong', '……哦。'], ['narr', '小道童狐疑地看了你一眼，扭头往山上跑了一段，又跑回来。']], { set: { yhBad: 1 } }], ['兵器', false, [['daotong', '兵器？！'], ['kang', '饼！烧饼！他口音重！'], ['narr', '小道童往山上瞄了一眼。']], { set: { yhBad: 1 } }]] },
  { q: [['daotong', '这车怎么这么沉？']],
    opts: [['冬瓜大', true, [['daotong', '……冬瓜确实大。']]], ['康掌柜胖', false, [['kang', '？？？'], ['daotong', '……掌柜在车外面站着呢。'], ['narr', '小道童摸出一张黄符，往山上一扔。符「呼」地飞了。']], { set: { yhBad: 1 } }]] },
  { q: [['daotong', '最后一个。'], ['daotong', '……你们见过一个卖药的姐姐吗？长得很好看的那个。']],
    opts: [['见过', true, [['narr', '小道童低下头，好半天没说话。'], ['daotong', '……过去吧。'], ['daotong', '栅栏我替你们开。别说是我开的。']]], ['没见过', true, [['daotong', '……哦。'], ['daotong', '过去吧。'], ['narr', '他背过身去，用袖子擦了一下眼睛。']]]] }];

Object.assign(CHOICES, {
  riji8: { q: [['narr', '五页日记摊在你手里。最后一页的墨还是湿的。'], ['zhen', '这东西，你打算怎么办？']], opts: [
    { l: '交给龙道长。他会记下来', set: { rijiLong: 1 }, aff: { long: 1 }, lines: [['me', '龙道长替别人拓了一辈子碑。'], ['me', '这件事，该有人记下来。'], ['zhen', '……记下来，后人就知道有个送饭的孩子，替一个怕死的人上了山。'], ['zhen', '行。']] },
    { l: '自己留着', set: { rijiKeep: 1 }, lines: [['narr', '你把日记叠好，揣进怀里，贴着那根狐尾铃铛。'], ['zhen', '……留着干什么？'], ['me', '不知道。'], ['me', '就是觉得，有些事，自己得记着。']] },
    { l: '烧掉', set: { rijiBurn: 1 }, aff: { zhen: 1 }, lines: [['narr', '你把日记凑到经阁的灯上。纸卷起来，一页一页地黑了。'], ['zhen', '烧了好。'], ['zhen', '一个怕死的人写的东西，不配留下来。'], ['narr', '火光里，最后那一行「今夜开门」，最后才烧掉。']] }] },
  jinding8: { q: [['narr', '屋里堆满了金子。金元宝、金叶子、金钉子——三根一模一样的金钉子，并排躺在一个锦盒里。'], ['kang', '让我来！我认金子认了三十年！']], opts: [
    { l: '左边那根', lines: [['narr', '康福贵拿起左边那根，放进嘴里，「咔」地一咬。'], ['kang', '……铜的。镀了金。'], ['narr', '他又拿起中间那根，一咬。'], ['kang', '……也是铜的。'], ['narr', '他拿起右边那根，没咬，掂了掂。'], ['kang', '这根，是真的。'], ['me', '你不咬一下？'], ['kang', '牙疼。']] },
    { l: '中间那根', lines: [['narr', '康福贵把中间那根放进嘴里，「咔」地一咬。'], ['kang', '……哎哟。'], ['kang', '铜的。牙崩了一小块。'], ['narr', '他捂着腮帮子，把剩下两根都掂了掂，挑出右边那根。'], ['kang', '这根。错不了。'], ['kang', '……回去记得给我报销牙钱。']] },
    { l: '都不是，金子全是假的', lines: [['kang', '全是假的？'], ['narr', '康福贵把三根钉子挨个掂了掂，又在袖子上蹭了蹭。'], ['kang', '……不对。右边那根，是真的。'], ['kang', '一屋子假金子，就藏一根真钉子。'], ['kang', '这种做法我熟——我爹当年藏私房钱，就是这么藏的。']] }] },
  farewellKang: { q: [['kang', '好兄弟！这是我全部的私房钱！'], ['narr', '康福贵塞过来一个沉甸甸的钱袋。'], ['kang', '……等一下。'], ['narr', '他又抽回去一半。'], ['kang', '这一半，给你办喜酒用！你得回来花！']], opts: [
    { l: '一定回来', aff: { kang: 1 }, gold: 500, lines: [['kang', '说好了！喜酒在醉仙楼办！我、我给你打八折！']] },
    { l: '钱你留着，喜酒的菜你做', aff: { kang: 2 }, lines: [['kang', '……好！满汉全席！'], ['kang', '这回一定有人来吃。']] }] },
  chess8: { q: [['long', '兄台，下一盘。'], ['narr', '书院的灯下，一盘棋下到一半。黑子白子绞在一起，谁也吃不掉谁。'], ['long', '该兄台了。']], opts: [
    { l: '跳马', lines: [['long', '好棋。'], ['narr', '龙道长拈起一枚棋子，在指间转了转，没落下去。']] },
    { l: '出车', lines: [['long', '兄台下棋，跟做人一样，直来直去。'], ['narr', '龙道长拈起一枚棋子，在指间转了转，没落下去。']] },
    { l: '（想了很久）', lines: [['long', '想得久，是好事。'], ['narr', '龙道长拈起一枚棋子，在指间转了转，没落下去。']] }] },
});

CAMPTALK[8] = [
  { id: 'z8weight', t: '他还是那么重', at: ['dffire', 'qdfire', 'jgfire'], when: S => mPast(S, 'm12'), lines: [
    ['narr', '珍姑娘坐在台阶上，抱着刀，一言不发。'],
    ['zhen', '我刚才扶他，他还是那么重。'],
    ['zhen', '小时候他背我，我嫌他背上全是油烟味。'],
    ['zhen', '……现在什么味都没有了。'],
    ['narr', '她把脸埋进膝盖里。过了很久，抬起头来，眼睛是干的。'],
    ['zhen', '走吧。'],
  ], aff: { zhen: 1 } },
  { id: 'z8afraid', t: '怕死', at: ['jgfire', 'hyfire', 'qdfire'], when: S => mPast(S, 'm15'), lines: [
    ['zhen', '我当捕快六年，抓过的人里，怕死的最多。'],
    ['zhen', '怕死不丢人。我也怕。'],
    ['zhen', '可他拿一个孩子的命去换自己的，换了一回，又换三百年。'],
    ['zhen', '……这才丢人。'],
    ['me', '我那时候，大概也怕。'],
    ['zhen', '那你还上去？'],
    ['me', '饭篮在我手里。总得有人把饭送上去。'],
    ['narr', '珍姑娘看了你很久。'],
    ['zhen', '……傻子。'],
  ], aff: { zhen: 1 } },
  { id: 'z8nails', t: '钉子是温的', at: ['hyfire', 'tkfire'], when: S => mPast(S, 'm21'), lines: [
    ['narr', '你把三枚钉子摆在火边。木的、金的、火的，还有怀里那枚水的。'],
    ['narr', '火光一跳一跳，钉子上的纹路像在呼吸。'],
    ['narr', '你好像听见有人在笑。很多人。'],
    ['narr', '「小师弟，长高了啊。」'],
    ['narr', '你抬起头，火边只有珍姑娘，在磨她的刀。'],
  ], aff: { zhen: 1 } },
  { id: 'k8cart', t: '送到门口', at: ['sjfire'], when: S => mPast(S, 'm7'), lines: [
    ['kang', '好兄弟，我、我就送到这儿了啊。'],
    ['narr', '康福贵蹲在菜车边上，一个劲地搓手。'],
    ['kang', '我胆子小。打架帮不上忙，还得你们分神照顾我。'],
    ['kang', '……可要是你们半天不下来，我就上去。'],
    ['kang', '我在门口喊，喊到有人理我为止。'],
  ], aff: { kang: 1 } },
];

const g8Patrol = S => !mPast(S, 'm23');   // 白云子死了，巡逻的道士也散了
