        w: g8Xt('xt8g', '铁匠铺的学徒二柱', [['narr', '二柱一个激灵，看见你手里的刀，脸都白了。'], ['narr', '「张师傅……张师傅让我来送铁钉……我送完了怎么没回去……」']]),
        h: { t: 'clue', grp: 'xianghuo', n: '东厢的香火簿', lines: [['narr', '东厢的条案上摊着一本香火簿。每一笔都写着名字、日子、香钱。'], ['narr', '「张大，屠户，香一炷，寿十年。」'], ['narr', '香钱那一栏写的不是钱。是「寿」。']] },
