        v: g8Xt('xt8i', '药铺隔壁的刘婶', [['narr', '刘婶看清你的脸，「哎呀」叫了一声。'], ['narr', '「阿土？你不是药铺那个……Ngoc 姑娘呢？她天天念叨你挑食……」'], ['narr', '她话说到一半，看见你的脸色，没再往下说。']]),
        z: g8Xt('xt8j', '镖局的趟子手小马', [['narr', '小马「腾」地跳起来，摸腰上的刀，刀不在。'], ['narr', '「镖！镖车被劫了！雷镖头还不知道——」'], ['narr', '他跑了两步，又跑回来：「镖车在东南边！我看见他们往那儿推的！」']]),
