QUIZ.guanqiang9 = [
  { q: [['guicha9', '站住！没有路引，一律不准进！'], ['liu', '（低声）让我来。'], ['liu', '差官，「一律不准进」——这个「一律」，原则上，是有例外的。'], ['guicha9', '……什么例外？']],
    opts: [['特事特办', true, [['liu', '对。我们这是特事。'], ['guicha9', '……特事？']]], ['给钱', false, [['guicha9', '贿赂阴差？罪加一等！'], ['liu', '……他开玩笑的。']]]] },
  { q: [['liu', '第二。路引这东西，阳间开的，阴间认不认——规矩里写了吗？'], ['guicha9', '……没写。']],
    opts: [['没写就是可以', true, [['liu', '法无禁止，即可为。'], ['guicha9', '……有道理。']]], ['没写就是不行', false, [['liu', '你站哪边的？！']]]] },
  { q: [['liu', '第三。差官要是不放行，耽误了阴阳两界的大事——这个责任，谁来担？'], ['guicha9', '……']],
    opts: [['差官担不起', true, [['guicha9', '……'], ['guicha9', '原则上……可以。'], ['narr', '「啪」。一个黑漆漆的章，盖在路引上。'], ['liu', '……'], ['liu', '（小声）其实我也没想到能行。']]], ['我们来担', false, [['liu', '你担？你担得起吗？'], ['guicha9', '……他说得对，你担不起。再来。']]]] }];

Object.assign(CHOICES, {
  mengpo9: { q: [['mengpo', '过奈何桥，要喝一碗汤。'], ['mengpo', '喝了，前尘往事，一笔勾销。'], ['mengpo', '喝不喝？']], opts: [
    { l: '不喝。我要记住', set: { soupNo: 1 }, lines: [['mengpo', '……三百年来，你是第二个说这句话的人。'], ['mengpo', '第一个，是一只白狐狸。'], ['mengpo', '她每年都来桥头站一站。不过桥，也不喝汤。就问我：「今年有没有一个送饭的孩子过去？」'], ['mengpo', '我说没有。她就走了。'], ['narr', '你接过汤碗，原样放回了桌上。']] },
    { l: '……我喝', set: { soupYes: 1 }, aff: { ngoc: 1 }, lines: [['narr', '你端起碗，一口喝干。'], ['narr', '……是水。'], ['mengpo', '骗你的。这碗是水。'], ['mengpo', '肯为了过桥，连自己都不要了的人——我孟婆记住你了。'], ['narr', '你什么都没忘。']] },
    { l: '婆婆，你的汤勺呢？', set: { soupAsk: 1 }, lines: [['mengpo', '……'], ['narr', '孟婆愣了一下，低头看了看手里那只缺了口的木碗。她一直是拿碗直接舀的。'], ['mengpo', '三百年了。头一回有人问我这个。'], ['mengpo', '丢了。在黄泉路上丢的。'], ['mengpo', '那天有个孩子不肯喝汤，哭着往回跑。我追他，勺子掉了，就再也没找着。'], ['mengpo', '……这碗你先端着。不喝也行。']] }] },
});

