const G9_WOLF = () => wPast(2, 'wolfSpared');
WQ[9] = {
  main: [
    // ---------- 序 · 鬼门关 ----------
    { id: 'm1', t: '坑口', d: '天坑边上，雷老虎在等你', goal: { talk: 'lei' }, auto: true,
      lines: S => [
        ['narr', '天亮的时候，你走到了白云观后山的天坑边。'],
        ['narr', '坑沿上插着镖局的大旗。镖师们举着火把，站成一圈。珍姑娘抱着刀，守在右边。'],
        ['lei', '来了？'],
        ['lei', '下去吧。上头有老子。'],
        ['narr', '刘师傅提着个包袱，从人群后面挤过来。'],
        ['liu', '我送你到鬼门关。'],
        ['zhen', '刘师傅，你——'],
        ['liu', '路引是我开的。出了岔子，得有人担着。'],
        ['liu', '原则上，这是我的分内事。'],
        ['narr', '铁蛋没有来。铁匠铺的方向，风箱声还在响。'],
      ], rw: { xp: 0.2 } },
    { id: 'm2', t: '鬼门关', d: '下到坑底', hint: '坑口正中，往下走。', goal: { enter: 'guimenguan' }, mark: 'gmgfire',
      lines: [['narr', '坑底没有底。你往下走了很久，脚下忽然一实——是一条石头路。'], ['narr', '路的尽头，一道黑石城墙横在面前，墙上三个大字：「鬼门关」。'], ['liu', '……三十年了。一点没变。']], rw: { xp: 0.2 } },
    { id: 'm3', t: '路引', d: '城门口站着守关的鬼差', goal: { talk: 'guicha9' }, quiz: 'guanqiang9', rw: { xp: 0.3 }, aff: { liu: 1 } },
    { id: 'm4', t: '翻脸', d: '进关', hint: '关门口。', goal: { reach: 'guanqian' }, mark: 'guanqian',
      get waves() { return wPast(7, 'pai7') ? undefined : [{ kind: 'battle', mon: 0, n: 3, lv: 30 }, { kind: 'battle', mon: 5, n: 3, lv: 30, mix: [0, 5, 7] }, { kind: 'elite', mon: 0, lv: 31, name: '守关鬼将' }]; },
      lines: S => wPast(7, 'pai7') ? [
        ['narr', '鬼差刚把章盖完，翻着名册的手忽然停住了。'],
        ['guicha9', '……等等。阳人？上头说了，阳人一律——'],
        ['narr', '墙根底下的小侧门「吱呀」一声开了。一个瘦瘦的兵卒探出头，冲你招手。'],
        ['xiaoliu', '这边！'],
        ['narr', '是王小六。他穿着守关鬼差的号衣，号衣大了一圈。'],
        ['xiaoliu', '牌位我看到了。刘师傅写的，字真丑。'],
        ['liu', '……'],
        ['xiaoliu', '谢谢。'],
        ['xiaoliu', '我在这儿看了三个月侧门，就等你来。快走，那个蠢牛头要反应过来了。'],
      ] : [
        ['narr', '鬼差刚把章盖完，翻着名册的手忽然停住了。'],
        ['guicha9', '……等等。'],
        ['guicha9', '阳人？上头说了，今天会有个阳人来——'],
        ['guicha9', '来了就拿下！'],
        ['liu', '……原则上，盖了章的，不能反悔。'],
        ['guicha9', '实际上——拿下！'],
      ],
      between: [[['liu', '（躲在石灯后面）程序！程序！他们不讲程序！']], [['narr', '关门里冲出来一个披甲的鬼将！']]],
      after: [['narr', '关门开了。'], ['liu', '我就送到这儿。'], ['liu', '原则上，阳人不能在阴间待太久。我这把老骨头，更待不住。'], ['narr', '刘师傅替你理了理衣领，把路引塞得更深一点。'], ['liu', '年轻人，记住——'], ['liu', '规矩是人定的。人比规矩大。'], ['narr', '他转身往坑口走，走得很慢，一次都没回头。']],
      set: { guanOpen: 1, xiaomen: 1 }, rw: { xp: 0.5 } },
    // ---------- 第一幕 · 黄泉路 ----------
    { id: 'm5', t: '阴阳镜', d: '黄泉路口，路边有一面破镜子', hint: '出了鬼门关往东，就是黄泉路。', area: 'huangquan9', goal: { get: 'yyj' }, mark: 'yyj',
      lines: [['narr', '路边的灰堆里，立着一面镜子。镜框是黑的，镜面裂了四道缝，缺了四块。'], ['narr', '镜框上刻着两个字：「阴阳」。'], ['narr', '你拿起来一照——镜子里的黄泉路，跟你眼前的不一样。路边站满了人。'], ['narr', '（得到「阴阳镜」：地图下方多了一个「阴阳镜」按钮，点一下就能在阳面和阴面之间来回切换。有的路只在一面走得通。）']],
      rw: { xp: 0.3, key: 'yinyangjing' } },
    { id: 'm6', t: '阴面', d: '过忘川上的断桥', hint: '断桥在阳面是断的。用阴阳镜照到阴面再过。', area: 'huangquan9', goal: { reach: 'yinlu' }, mark: 'yinlu',
      lines: [['narr', '你走过那座在阳面断掉的桥。脚底下踩着的，是一块一块发着幽光的石板。'], ['narr', '桥这头，路边坐着、站着、蹲着好些鬼。'], ['narr', '有几张脸，你认得。']], rw: { xp: 0.3 } },
    { id: 'm7', t: '熟面孔', d: '阴面的路边，有几个你认识的人（{n}/4）', hint: '要照到阴面才看得见（{n}/4）', goal: { talks: ['shutong', 'wang', 'shemuhun', 'bingmutou'] },
      tl: {
        shutong: [['shutong', '恩、恩公？您、您真的死了？！'], ['me', '没有。来接个人。'], ['shutong', '吓、吓死我了……'], ['shutong', '我在这儿等我娘。'], ['shutong', '鬼市的河灯我不描了。她记得我，我就不用描了。'], ['shutong', '可我想等她。等她老了，下来了，我陪她一起过桥。'], ['shutong', '……她怕黑。']],
        wang: [['wang', '年轻人，又见面了。'], ['wang', '这回我是真走不动了。'], ['narr', '王老头坐在路边，手里攥着那本发霉的名册——刘师傅三十年前漏写他的那本。'], ['wang', '偷来的三十年，到头了。'], ['wang', '我孙子……娶媳妇了。我偷偷去看了。新娘子很俊。'], ['wang', '够了。']],
        shemuhun: [['narr', '一条淡青色的影子盘在石头上，看见你，抬起了头。'], ['shemuhun', '……是你。'], ['shemuhun', '那个道士跟我说，吃了狐狸精的心，就能化龙。'], ['shemuhun', '我信了。我在沼泽里活了一千年，就想看一眼天上是什么样子。'], ['shemuhun', '死了以后才知道，龙不是吃出来的。'], ['shemuhun', '……替我跟那只狐狸说一声，对不住。']],
        bingmutou: [['narr', '一个年轻的猎人蹲在路边，怀里抱着一张弓。弓背上刻着两个名字：「冰石头」「冰木头」。'], ['bingmutou', '你从上面下来的？'], ['bingmutou', '见过我哥吗？冰家村的，打猎的，个子很高，脾气很犟。'], ['me', '见过。他还在找你。'], ['bingmutou', '……傻子。'], ['bingmutou', '告诉他，我脚快。先走一步。'], ['bingmutou', '让他别急着下来。']],
      }, rw: { xp: 0.4 } },
    { id: 'm8', t: '追兵', d: '路中间，鬼差的追兵赶上来了', hint: '黄泉路中段。', area: 'huangquan9', goal: { reach: 'zhuibing' }, mark: 'zhuibing',
      get waves() { return G9_WOLF() ? undefined : [{ kind: 'battle', mon: 0, n: 3, lv: 31 }, { kind: 'battle', mon: 5, n: 3, lv: 31, mix: [0, 2, 5] }, { kind: 'elite', mon: 0, lv: 32, name: '追兵头子' }]; },
      lines: S => G9_WOLF() ? [
        ['narr', '身后传来一片铁链声。鬼门关的追兵赶上来了，黑压压一片。'],
        ['narr', '你握紧了刀。'],
        ['narr', '然后，阳面那边传来一声狼嚎。'],
        ['narr', '一头巨大的黑狼从阳面的路上冲过来，身后跟着一群狼，扑进了鬼差堆里。'],
        ['narr', '是黑风林的狼王。'],
        ['narr', '它咬住领头那个鬼差的锁链，回头看了你一眼。'],
        ['narr', '你放过它一回。它记得。'],
        ['narr', '（狼王带着狼群，替你挡住了追兵。）'],
      ] : [['narr', '身后传来一片铁链声。鬼门关的追兵赶上来了，黑压压一片。'], ['narr', '没有人帮你。你握紧了刀。']],
      between: [[['narr', '还有！']], [['narr', '一个大个子挤了上来！']]],
      after: S => G9_WOLF() ? [['narr', '狼群把追兵赶回了鬼门关。狼王站在阳面的石头上，冲你低低地叫了一声，转身走了。']] : [['narr', '最后一个追兵散成了黑烟。你喘着气，往东走。']],
      rw: { xp: 0.5 } },
    { id: 'm9', t: '墙洞', d: '东边一道石墙挡住了路。去望乡台', hint: '墙上的洞只在阳面开着。回到阳面再过。', goal: { enter: 'wangxiangtai' }, mark: 'wxfire',
      lines: [['narr', '穿过墙洞，是一座高台。台下熙熙攘攘，全是鬼。'], ['narr', '每个鬼都往台上挤。挤上去了，站在边上，往下看一眼，然后就哭。'], ['narr', '这是望乡台。站在台上，能看见阳间的家。']], rw: { xp: 0.3 } },
    // ---------- 第二幕 · 奈何桥 ----------
    { id: 'm10', t: '判官', d: '望乡台下坐着一个判官', goal: { talk: 'panguan' },
      lines: [
        ['panguan', '阳人？'],
        ['narr', '判官坐在一张案子后面，案上堆着一摞一摞的卷宗。他抬头看了你一眼，又低下头。'],
        ['panguan', '本官管望乡台。谁该看几眼，谁该站多久，本官说了算。'],
        ['panguan', '你要过奈何桥？桥头有孟婆。过了桥，就是鬼门。牛头马面守着。'],
        ['panguan', '……你那张路引，章是阳间的。牛头马面不一定认。'],
        ['panguan', '想补个阴司的章，来找本官。'],
        ['narr', '（望乡台下能买东西了：孟婆的小徒弟卖茶点，判官卖阴司的兵器，鬼货郎也在。冥币不够，在判官那里拿银子换。）'],
      ], rw: { xp: 0.2, mb: 60 } },
    { id: 'm11', t: '孟婆', d: '去奈何桥头，见孟婆', hint: '望乡台往东。', goal: { talk: 'mengpo' }, choice: 'mengpo9',
      lines: [['narr', '桥头一张小木桌，桌上摆着一口大锅。锅边坐着一个白头发的老婆婆，正拿一只缺了口的木碗往外舀汤。'], ['mengpo', '又来一个。'], ['mengpo', '……咦。活的？']], rw: { xp: 0.3 } },
    { id: 'm12', t: '桥上的少年', d: '上奈何桥', goal: { reach: 'qiaozhong' }, mark: 'qiaozhong',
      lines: [
        ['narr', '你走上奈何桥。'],
        ['narr', '桥中间，有一个少年。'],
        ['narr', '十五六岁，瘦瘦的，穿着打补丁的短褂，提着一只饭篮。饭篮很沉，他提得一歪一歪的。'],
        ['narr', '他从你身边走过去。'],
        ['narr', '你闻到了窝头的味道。还有咸菜，还有鸡汤。'],
        ['narr', '他没有看你。他一直往桥那头走。'],
      ], rw: { xp: 0.3 } },
    { id: 'm13', t: '记起来了', d: '跟着那个少年，走到桥那头', goal: { reach: 'qiaotou' }, mark: 'qiaotou',
      lines: [
        ['narr', '少年走到桥那头，停了下来，回头看了一眼。'],
        ['narr', '他看的是山坡下面的草丛。'],
        ['narr', '然后他转回去，接着往前走，走进了黑雾里，不见了。'],
        ['narr', '你站在桥头，一动不动。'],
        ['narr', '然后，所有的东西都回来了。'],
        ['narr', '山脚的小屋。屋顶漏雨，下雨天要拿盆接。'],
        ['narr', '张婶的窝头，又硬又香。李叔的咸菜，齁咸。王奶奶熬鸡汤，一边熬一边念叨：「镇妖师辛苦，得补补。」'],
        ['narr', '五个镇妖师。青木子爱笑，金不换爱钱，烈阳子嗓门大，玄冰子不说话，白云子……白云子总是站在最后面。'],
        ['narr', '那天你提着饭篮上山。他们五个人站在坑口，四个人。'],
        ['narr', '青木子拍了拍你的头：「小土，你回去。」'],
        ['narr', '你说：「白云子道长说他去拿法器，让我先替他站一会儿。」'],
        ['narr', '四个人互相看了一眼。没有人说话。'],
        ['narr', '后来……'],
        ['narr', '后来有一只白狐狸，从林子里跑出来，挡在你前面。'],
        ['narr', '她说：「我等你。」'],
        ['narr', '你全都记起来了。'],
      ], rw: { xp: 0.5 } },
    // ---------- 第三幕 · 鬼门（牛头马面） ----------
    { id: 'm14', t: '马面', d: '过了桥，就是鬼门', goal: { talk: 'mamian' },
      lines: [['mamian', '又是你！'], ['narr', '马面看见你，往后跳了一步，手里的哭丧棒差点掉了。'], ['mamian', '鬼市那回就是你！打得我三天没上班！'], ['narr', '他身后，一个牛头大汉扛着一柄大斧，慢慢站了起来。'], ['niutou', '……就是他？'], ['mamian', '就是他！'], ['niutou', '规矩就是规矩。阳人过鬼门，先过我们俩。']], rw: { xp: 0.2 } },
    { id: 'm15', t: '牛头马面', d: '鬼门前，牛头马面拦着', goal: { fight: 'boss9' }, mark: 'boss9',
      lines: [['niutou', '来。'], ['mamian', '这回我们俩一起！']],
      after: [['narr', '牛头一屁股坐在地上，斧子扔到一边。马面趴在地上，直喘气。'], ['niutou', '……打得好。'], ['mamian', '我们……我们早就不想守这破门了。']],
      set: { bossDead: 1 }, rw: { xp: 0.8, item: 'rare' } },
    { id: 'm16', t: '盟友', d: '牛头有话说', goal: { talk: 'niutou' },
      lines: [
        ['niutou', '阳人，你知道我们为什么守这扇门吗？'],
        ['niutou', '门底下关着魔尊。三百年前，五根钉子一颗狐丹把它锁住，阎王爷派我们俩来看门。'],
        ['niutou', '看了三百年。'],
        ['mamian', '这三百年，魔尊天天往外渗魔气。鬼魂沾了魔气，就不肯投胎，往阳间跑。'],
        ['mamian', '跑一个，扣我们一回绩效。'],
        ['niutou', '年年考核不合格。'],
        ['mamian', '年年！'],
        ['niutou', '……你要下去找魔尊？'],
        ['me', '下去接一个人。'],
        ['niutou', '那就算我们一份。'],
      ], rw: { xp: 0.3 } },
    // ---------- 第四幕 · 正气 ----------
    { id: 'm17', t: '坑口急报', d: '马面接到了急报', goal: { talk: 'mamian' },
      lines: [
        ['mamian', '这个给你。阴司通行。'],
        ['mamian', '原则上——嘶，我怎么也学会这一句了——原则上，你是第一个活着走过去的。'],
        ['narr', '马面话没说完，一个小鬼差连滚带爬地跑过来，跪在地上。'],
        ['mamian', '慌什么？'],
        ['narr', '小鬼差说了几句。马面的脸色变了。'],
        ['mamian', '……魔尊的影子往上爬了。'],
        ['mamian', '你们把钉子都带下来了，上头的封印松了。底下的鬼潮，正顺着那个天坑往阳间涌。'],
        ['niutou', '天坑上面，是什么地方？'],
        ['me', '青石镇。'],
        ['mamian', '拿着通行，快回去！'],
      ], tele: ['kengkou', 'f', 'kkfire'], rw: { xp: 0.2, key: 'yinsi' } },
    { id: 'm18', t: '守坑口', d: '鬼潮从坑底往上涌。和镖局的人一起守住坑口', hint: '坑口正中。', goal: { reach: 'kkwave' }, mark: 'kkwave',
      waves: [{ kind: 'battle', mon: 2, n: 4, lv: 33, mix: [1, 2, 4] }, { kind: 'battle', mon: 1, n: 3, lv: 33, mix: [1, 4, 7] }, { kind: 'elite', mon: 3, lv: 33, name: '爬出坑口的骨龙' }],
      lines: [
        ['narr', '你冲出坑口的时候，天是黑的。不是夜里那种黑——是鬼潮遮住了太阳。'],
        ['narr', '坑底的黑气一浪一浪地往上涌，每一浪里，都是张牙舞爪的鬼。'],
        ['lei', '小子！你回来了！'],
        ['narr', '雷老虎满脸是血，大刀卷了刃。镖局的兄弟倒了一半。'],
        ['lei', '旗还在！老子说了，旗在人在！'],
        ['zhen', '左边！'],
      ],
      between: [[['lei', '第二波！兄弟们，顶住！']], [['narr', '一条骨龙从坑底爬了上来，尾巴一甩——'], ['narr', '「咔嚓」。镖局的大旗，断了。'], ['lei', '……老子的旗！']]],
      after: [['narr', '骨龙倒下去，摔回了坑底。'], ['narr', '可坑底的黑气还在涌。一浪比一浪高。'], ['zhen', '……打不完的。'], ['zhen', '底下有多少，就能上来多少。'], ['narr', '雷老虎拄着断了的旗杆，喘着粗气，没说话。']],
      rw: { xp: 0.6 } },
    { id: 'm19', t: '正气灯', d: '龙道长提着一盏灯，走上了坑口', goal: { talk: 'long' },
      lines: S => [
        ['narr', '人群后面，有个人慢慢走了过来。'],
        ['narr', '青布长衫，手里提着一盏灯。'],
        ['narr', '是龙道长。'],
        ...(wkeys().zhengqideng ? [['narr', '那盏灯，你认得。铁蛋做的灯骨，每个角上刻着一个「铁」字；康福贵的陈年香油；灯纸上是他写的四个字：「天地正气」。']]
          : [['narr', '那是一盏普普通通的油灯。灯纸是新糊的，墨还没干，上面是四个字：「天地正气」。']]),
        ['long', '兄台回来了。'],
        ['me', '道长，你来干什么？这里——'],
        ['long', '在下手无缚鸡之力，打不了鬼。'],
        ['long', '可在下读过一首诗。'],
        ['narr', '他从怀里掏出那本卷了边的小册子。封皮上三个字：《正气歌》。'],
        ['long', '文丞相当年在牢里写的。他一个读书人，关在土牢里，水气、土气、日气、火气、米气、人气、秽气，七种恶气熏着他，熏了两年。'],
        ['long', '他没病。'],
        ['long', '他说，他胸中有一股正气。七种恶气，敌不过这一种。'],
        ['narr', '龙道长把册子揣回怀里。他不用看。他背得出来。'],
        ['long', '兄台，替在下挡一挡。'],
        ['long', '在下念完，就好了。'],
      ], aff: { long: 2 }, rw: { xp: 0.2 } },
    { id: 'm20', t: '正气歌', d: '龙道长站上坑口最前面，开始念《正气歌》。守住他', hint: '坑口最前面。他念完之前，不能让他倒下。', goal: { reach: 'kkward' }, mark: 'kkward',
      waves: [{ kind: 'battle', lv: 33, ward: { name: '龙道长', spr: 'scholar', need: 12, hp: 1.25, arm: 1.2, spd: 80, keep: 3, n0: 3, mons: [1, 2, 4, 7], lines: ZQG,
        say: { 6: '兄台，在下手无缚鸡之力，读了一辈子书。今天才知道，书上那些人，为什么不怕死。', 10: '天下兴亡，匹夫有责。在下……也是匹夫。' },
        end: '最后一句念完，正气灯的光冲天而起。鬼潮像退潮一样，「哗」地退回了深渊。' } }],
      lines: [['narr', '龙道长走到坑口最前面，把灯举过头顶。'], ['narr', '鬼潮看见了光，一齐扑了过来。'], ['long', '天地有正气——']],
      after: [
        ['narr', '天亮了。'],
        ['narr', '鬼潮退回了深渊，坑底的黑气，一丝一丝缩了回去。'],
        ['narr', '龙道长还站在坑口。'],
        ['narr', '他的长衫是灰的。他的脸是灰的。他举着灯的那只手，也是灰的。'],
        ['narr', '他化成了一尊石像。'],
        ['narr', '手里那盏灯，还亮着。'],
      ], set: { longStone: 1 }, rw: { xp: 0.8 } },
    { id: 'm21', t: '断旗', d: '雷老虎拄着断旗，走到了石像边上', goal: { talk: 'lei' },
      lines: [
        ['narr', '谁也没有说话。'],
        ['narr', '雷老虎拄着那根断了的旗杆，一步一步走到石像边上。'],
        ['narr', '他把断旗插在石像脚下，插得很深。'],
        ['lei', '……老子押了一辈子镖。'],
        ['lei', '没押过读书人。'],
        ['lei', '早知道你这么硬气，老子该请你喝酒的。'],
        ['narr', '珍姑娘站在旁边，手按着刀柄，按得指节发白。'],
        ['narr', '她一直没哭。'],
      ], aff: { zhen: 1 }, rw: { xp: 0.2 } },
    { id: 'm22', t: '土之钉', d: '铁蛋从山下跑上来了', goal: { talk: 'tiedan' },
      lines: [
        ['tiedan', '哥——！'],
        ['narr', '铁蛋满身是灰，跑得鞋都掉了一只，怀里抱着一块包了七八层湿布的东西。'],
        ['tiedan', '打好了！打好了！我爹打了一天一夜，刚淬完火！'],
        ['narr', '他把湿布一层一层揭开。里面是一枚土黄色的钉子，还在冒热气。'],
        ['tiedan', '我爹说，这是他这辈子，打得最好的一件。'],
        ['narr', '他抬起头，看见了坑口那尊石像。'],
        ['narr', '钉子差点从他手里掉下去。'],
        ['tiedan', '……龙先生？'],
        ['narr', '没有人回答他。'],
        ['narr', '铁蛋走过去，伸手摸了摸石像的袖子。然后他转过身，把钉子塞进你手里，用两只手攥着你的手，攥得很紧。'],
        ['tiedan', '哥。'],
        ['tiedan', '你得回来。'],
      ], rw: { xp: 0.2, key: 'tuding' } },
    { id: 'm23', t: '下去', d: '五枚钉子齐了。和珍姑娘告别', goal: { talk: 'zhen' }, final: true,
      lines: [
        ['narr', '木、金、火、水、土。'],
        ['narr', '五枚钉子，躺在你手心里，一枚挨着一枚，都是温的。'],
        ['narr', '你走到石像跟前，伸手去接那盏灯。'],
        ['narr', '石像的手指，松开了。'],
        ['narr', '灯落在你手里。灯纸上「天地正气」四个字，亮得像刚写上去的。'],
        ['zhen', '……走吧。'],
        ['zhen', '令牌，回来还我。'],
        ['me', '嗯。'],
        ['zhen', '还有——'],
        ['narr', '珍姑娘别过脸去。'],
        ['zhen', '把她带回来。'],
        ['zhen', '龙道长那盘棋，还等着人下完。'],
        ['narr', '你提着灯，跳进了深渊。'],
      ], rw: { xp: 0.4, key: 'zhengqi10' } },
  ],
  side: [
    { id: 'S1', t: '孟婆的汤勺', giver: 'mengpo', when: S => mPast(S, 'm11'),
      offer: [['mengpo', '三百年前，我在黄泉路上丢了一把汤勺。'], ['mengpo', '木头的，勺头缺个小口。柄上刻着「孟氏」。'], ['mengpo', '阳面我找遍了。阴面……我老了，照不动镜子了。'], ['mengpo', '你要是看见了，捡回来给我。']],
      steps: [
        { d: '在黄泉路的阴面找孟婆的汤勺', hint: '黄泉路东段，阴面才看得见。', area: 'huangquan9', goal: { clue: 'tangshao', n: 1 }, mark: 'clue:tangshao' },
        { d: '把汤勺还给孟婆', goal: { talk: 'mengpo' }, lines: [['narr', '孟婆接过汤勺，翻来覆去地看。'], ['mengpo', '……是它。'], ['mengpo', '那天那个哭着往回跑的孩子，后来我听说，他回阳间去了。'], ['mengpo', '活了八十多岁，儿孙满堂。'], ['mengpo', '我这把勺子，丢得值。'], ['narr', '她把那只缺了口的木碗递给你。'], ['mengpo', '这只碗跟了我三百年。生死簿上的墨，见了它就洒——它装过太多不想忘的人。'], ['mengpo', '拿着。我有勺子了。']] }],
      rw: { xp: 0.5, key: 'tangwan' } },
    { id: 'S2', t: '补章', giver: 'panguan', when: S => mPast(S, 'm10'),
      offer: [['panguan', '你那张路引，拿来本官看看。'], ['narr', '判官把路引凑到灯底下，看了很久。'], ['panguan', '……「原则上」。'], ['panguan', '这个刘师爷，三十年前来备案，也是满口原则上。'], ['panguan', '章是好章，可惜是阳间的。补个阴司的章，牛头马面的勾魂锁就认得了。'], ['panguan', '按规矩，补章要三份阴司文书。阴兵、勾魂使身上都有，他们拿来当草纸用。']],
      steps: [
        { d: '从阴兵、勾魂使身上找阴司文书（{n}/3）', hint: '黄泉路上的阴兵、勾魂使（{n}/3）', area: 'huangquan9', goal: { drop: 'wenshu', n: 3, mon: [0, 5], p: 0.5, dn: '阴司文书' }, mark: 'monm:0/5' },
        { d: '把文书交给判官', goal: { talk: 'panguan' }, lines: [['narr', '判官把三份文书往案上一拍，拿起一枚黑玉大印，「啪」地盖在路引上。'], ['narr', '两个章并排盖着。一个红的，一个黑的。红的盖歪了，黑的盖得端端正正。'], ['panguan', '回去告诉刘师爷。'], ['panguan', '本官当年给他磨了三个月的墨，他一个谢字都没说。'], ['panguan', '……让他好好活着。别急着下来备案。']] }],
      rw: { xp: 0.5, key: 'luyin2' } },
    { id: 'S3', t: '补镜', giver: 'wang', when: S => mPast(S, 'm7'),
      offer: [['wang', '年轻人，你那面镜子，借我看看。'], ['narr', '王老头接过阴阳镜，眯着眼睛对着光照。'], ['wang', '裂了四道，缺了四块。'], ['wang', '我活着的时候，是磨镜子的。走街串巷，「磨剪子嘞——戗菜刀——磨镜子——」'], ['wang', '这镜子的碎片，就散在这条路上。阴面才看得见。你捡回来，我给你补。']],
      steps: [
        { d: '在黄泉路的阴面捡镜片（{n}/4）', hint: '黄泉路西、中、东三段都有，阴面才看得见（{n}/4）', area: 'huangquan9', goal: { clue: 'jingpian', n: 4 }, mark: 'clue:jingpian' },
        { d: '把镜片交给王老头（阴面）', goal: { talk: 'wang' }, lines: [['narr', '王老头蹲在路边，从怀里摸出一块磨刀石、一小罐胶，一块一块地往镜子上补。'], ['narr', '补完最后一块，他朝镜面哈了口气，拿袖子擦了擦。'], ['wang', '好了。'], ['wang', '补好的阴阳镜，不光能照你自己。'], ['wang', '照着谁，谁就过去——一个照进阴面，一个留在阳面，打架的时候，够他们俩受的。'], ['wang', '……这是我这辈子，最后一面镜子。']] }],
      rw: { xp: 0.5, key: 'yinyang9' } },
    { id: 'S4', t: '冰木头的话', giver: 'bingmutou', when: S => mPast(S, 'm7'),
      offer: [['bingmutou', '你……能帮我个忙吗？'], ['narr', '冰木头从怀里摸出一只骨哨。'], ['bingmutou', '小时候我跟我哥进山，走散了，就吹这个。他一听见，就知道我在哪儿。'], ['bingmutou', '听说望乡台上能看见阳间。你替我站上去，吹一声。'], ['bingmutou', '他听见了，就知道我没事。']],
      steps: [{ d: '站上望乡台，吹响冰木头的骨哨', hint: '望乡台上，台边。', goal: { reach: 'wangxiang' }, mark: 'wangxiang', set: { bingmsg: 1 },
        lines: [['narr', '你站在望乡台边上，往北看。'], ['narr', '云底下，是一片白茫茫的雪原。雪原边上，有一个小村子，屋顶上冒着烟。'], ['narr', '一个高个子猎人蹲在村口，正在磨一把刀。'], ['narr', '你吹响了骨哨。'], ['narr', '「呜——」'], ['narr', '猎人的手停了。'], ['narr', '他慢慢站起来，抬起头，往天上看。看了很久。'], ['narr', '然后他笑了一下。'], ['narr', '他把刀插回腰上，转身进了屋。'], ['narr', '屋里的灯，亮了。']] }],
      rw: { xp: 0.4, item: 'rare' } },
    { id: 'S5', t: '阿福过桥', giver: 'shutong', when: S => mPast(S, 'm7'),
      offer: [['shutong', '恩公……'], ['shutong', '我想好了。我不等了。'], ['shutong', '我娘要是下来，看见我还在路边站着，会难过的。'], ['shutong', '可我想……再看她一眼。'], ['shutong', '望乡台上，能看见吗？']],
      steps: [
        { d: '带阿福上望乡台', hint: '望乡台上，台边。', goal: { reach: 'wangxiang' }, mark: 'wangxiang',
          lines: [['narr', '阿福扒着望乡台的栏杆，踮着脚往下看。'], ['narr', '青石镇。阿福家的小院子里，一个女人坐在门槛上，在糊一盏河灯。'], ['narr', '灯上写着两个字：「阿福」。'], ['shutong', '她写「福」字，右边的「田」还是写得大……'], ['narr', '阿福看了很久。'], ['shutong', '好了。'], ['shutong', '恩公，我去过桥了。']] },
        { d: '在奈何桥头，跟孟婆说一声', goal: { talk: 'mengpo' }, lines: [['mengpo', '这孩子我认得。在忘川边上描了三年河灯。'], ['mengpo', '汤不用喝了。'], ['mengpo', '记着你娘吧。下辈子，还给她当儿子。'], ['narr', '阿福冲你鞠了一躬，跑上了奈何桥。跑到桥中间，他回头挥了挥手。'], ['narr', '然后就不见了。']] }],
      rw: { xp: 0.4, gold: 400 } },
    { id: 'S6', t: '蛇母的蜕', giver: 'shemuhun', when: S => mPast(S, 'm7'),
      offer: [['shemuhun', '我身上还剩一层蜕。'], ['shemuhun', '活了一千年，就剩这么点东西。'], ['shemuhun', '万毒沼边上有个老渔婆，我吓唬过她一辈子。她儿子……是我吃的。'], ['shemuhun', '把这层蜕放进忘川。忘川通天下的水，它会漂到她门口。'], ['shemuhun', '蛇蜕入药，能治她的老寒腿。'], ['shemuhun', '……就当我还她的。']],
      steps: [{ d: '把蛇蜕放进忘川', hint: '奈何桥西岸，阴面才能下到水边。', goal: { reach: 'wangchuan' }, mark: 'wangchuan',
        lines: [['narr', '你蹲在忘川边上，把那层薄薄的蛇蜕放进水里。'], ['narr', '黑色的河水托着它，慢慢漂远了。'], ['narr', '很久以后，万毒沼边上的一间小屋门口，一个老婆婆早起开门，在门槛边捡到一层蛇蜕。'], ['narr', '她看了很久，什么也没说，把蛇蜕收进了药罐里。']] }],
      rw: { xp: 0.4, item: 'rare' } },
    { id: 'S7', t: '赎回的记忆', giver: 'huolang9', when: S => g9Mem(),
      offer: [['huolang9', '哟，阳人。'], ['huolang9', '您上回在鬼市押给我的那段记忆，我一直没卖。'], ['huolang', '那种货，留着压箱底的。'], ['huolang', '您要是想赎回去——一百二十枚冥币。童叟无欺～']],
      steps: [
        { d: '在鬼货郎那里，把记忆赎回来（一百二十枚冥币）', hint: '望乡台下，鬼货郎的担子。', goal: { get: 'jiyiping' }, mark: 'huolang9' },
        { d: '打开瓶子', goal: { talk: 'huolang9' }, lines: S => { const w = g9MemWho();
          const L = { ngoc: [['narr', '你拔开瓶塞。一缕白烟钻进你的眉心。'], ['narr', '「冻坏了，没人付药钱。」'], ['narr', '暖炉烫得你一哆嗦。她的手冻得通红。她别过脸去，耳朵也是红的。'], ['narr', '……你想起来了。'], ['narr', '胸口那块空了的地方，又暖了。']],
            zhen: [['narr', '你拔开瓶塞。一缕白烟钻进你的眉心。'], ['narr', '篝火噼啪响。她抱着刀坐在火边，一夜没合眼。天快亮的时候，她把自己的披风盖在了你身上。'], ['narr', '……你想起来了。那天晚上的火，为什么那么暖。']],
            kang: [['narr', '你拔开瓶塞。一缕白烟钻进你的眉心。'], ['narr', '金锁在手心里，热乎乎的。康福贵哭得鼻涕都出来了，说「我爹给我打的，戴了四十年」。'], ['narr', '……你想起来了。']],
            long: [['narr', '你拔开瓶塞。一缕白烟钻进你的眉心。'], ['narr', '书院的灯下，一个读书人弯着腰看拓片，看到入神，抬起头冲你笑：「兄台。」'], ['narr', '……你想起来了。他第一次这么叫你的时候，你心里一热。']] };
          return [...L[w], ['huolang9', '……好货就该回到原主人手里。'], ['huolang9', '下回别乱当了。']]; } }],
      rw: { xp: 0.4, flag: 'mem7redeem' } },
    { id: 'S8', t: '王小六的兄弟们', giver: 'xiaoliu', when: S => wPast(7, 'pai7') && mPast(S, 'm4'),
      offer: [['xiaoliu', '恩人。'], ['xiaoliu', '我那三千个兄弟，城破那天跟我一起死的。'], ['xiaoliu', '他们的魂散在黄泉路上，被抓去当了阴兵、骷髅。脖子上还挂着军牌。'], ['xiaoliu', '你帮我把军牌取回来，我拿去给刘师傅。'], ['xiaoliu', '……我一个人有牌位，他们没有，我不踏实。']],
      steps: [
        { d: '从阴兵、黄泉骷髅身上找军牌（{n}/3）', hint: '黄泉路、鬼门关的阴兵和骷髅（{n}/3）', area: 'huangquan9', goal: { drop: 'junpai', n: 3, mon: [0, 7], p: 0.5, dn: '一块锈了的军牌' }, mark: 'monm:0/7' },
        { d: '把军牌交给王小六', goal: { talk: 'xiaoliu' }, lines: [['narr', '王小六把三块军牌捧在手里，一块一块擦干净。'], ['xiaoliu', '「赵大」……「孙二狗」……「李满仓」……'], ['xiaoliu', '赵大是伙夫，煮的饭全营最难吃。孙二狗胆子小，打雷都躲我身后。李满仓……李满仓说打完这一仗就回家娶媳妇。'], ['xiaoliu', '三千个，我都记得。'], ['xiaoliu', '慢慢来。一块一块地找。'], ['xiaoliu', '找齐了，让刘师傅写三千个牌位。他字丑，但是写得慢，写得认真。']] }],
      rw: { xp: 0.5, item: 'rare' } },
    { id: 'S9', t: '康福贵的阳寿', giver: 'panguan', when: S => mPast(S, 'm10'),
      offer: [['panguan', '阳人，你认识一个姓康的胖子吗？'], ['panguan', '他的名字在生死簿上，被人划过一道，又被人描回来了。本官头一回见这种事。'], ['panguan', '想看看他还能活多久吗？']],
      steps: [{ d: '跟判官翻翻生死簿', goal: { talk: 'panguan' }, lines: [['narr', '判官翻开生死簿，手指头一行一行往下划。'], ['panguan', '「康福贵。醉仙楼掌柜。阳寿……四十九。」'], ['me', '……'], ['panguan', '等等，后面还有字。'], ['panguan', '「……年后」。'], ['panguan', '四十九年后。'], ['panguan', '这胖子命硬得很。九十八岁，吃饭的时候笑死的。'], ['narr', '你在望乡台下站了一会儿，笑出了声。']] }],
      rw: { xp: 0.3, gold: 300 } },
    { id: 'S10', t: '通缉：黄泉二恶', giver: 'panguan', when: S => mPast(S, 'm10'),
      offer: [['panguan', '黄泉路上有两个刺头，本官早就想办了。'], ['panguan', '一个是骨龙王，一个是勾魂使统领。阴兵管不住，阎王爷也懒得管。'], ['panguan', '你替本官办了，赏银照付。']],
      steps: [
        { d: '在黄泉路打倒骨龙王和勾魂使统领（{n}/2）', hint: '黄泉路东段北边、中段南边（{n}/2）', area: 'huangquan9', goal: { kill: 'tj9', n: 2 }, mark: 'mon:tj9' },
        { d: '回望乡台找判官', goal: { talk: 'panguan' }, lines: [['panguan', '办得好。'], ['panguan', '本官给你记一功。'], ['panguan', '……阳人的功，阴间记了也没用。可本官还是要记。程序就是程序。']] }],
      rw: { gold: 800, xp: 0.5, item: 'rare' } },
  ],
};

// ==================== 第十章 · 九幽深渊（主题：这次换我）  + 结局 ====================
